function textoHorarios(horarios) {
  if (!horarios || !horarios.length) return "-";
  return horarios.map(h => `${h.dia_semana} ${(h.hora||"").slice(0,5)}`).join(", ");
}
function claveOrdeHorario(horarios) {
  if (!horarios || !horarios.length) return Infinity;
  const minutos = (hora) => { const [h,m] = (hora||"0:0").split(":").map(Number); return h*60+m; };
  return Math.min(...horarios.map(h => {
    const dia = DIAS_SEMANA.indexOf(h.dia_semana);
    return (dia === -1 ? 99 : dia) * 10000 + minutos(h.hora);
  }));
}
const DIA_SEMANA_JS = { "Luns": 1, "Martes": 2, "Mércores": 3, "Xoves": 4, "Venres": 5 };
function contarSesionsRestantes(horarios, desdeISO, ataISO) {
  if (!horarios || !horarios.length || !ataISO) return null;
  const diasObxectivo = new Set(horarios.map(h => DIA_SEMANA_JS[h.dia_semana]).filter(Boolean));
  if (!diasObxectivo.size) return null;
  const fin = new Date(ataISO + "T00:00:00");
  if (isNaN(fin.getTime())) return null;
  let d = desdeISO ? new Date(desdeISO + "T00:00:00") : new Date();
  d.setDate(d.getDate() + 1);
  let conta = 0;
  let iteracions = 0;
  while (d < fin && iteracions < 730) {
    if (diasObxectivo.has(d.getDay())) conta++;
    d.setDate(d.getDate() + 1);
    iteracions++;
  }
  return conta;
}

