function exportarClasePDF(alumno, fila, obrasSeleccionadas, pesos, opcions) {
  const doc = new window.jspdf.jsPDF();
  cabeceiraPDF(doc, "Rexistro de clase");
  let y = 48;
  doc.setFontSize(10);
  doc.setFont(undefined, "bold"); doc.text("Alumno:", 14, y);
  doc.setFont(undefined, "normal"); doc.text(`${alumno.nome} ${alumno.apelidos || ""}`, 45, y); y += 7;
  doc.setFont(undefined, "bold"); doc.text("Data:", 14, y);
  doc.setFont(undefined, "normal"); doc.text(fila.data || "-", 45, y); y += 10;

  if (opcions.obraProgreso && obrasSeleccionadas.length) {
    doc.setFontSize(11); doc.setFont(undefined, "bold"); doc.text("Repertorio e progreso", 14, y); y += 7;
    doc.setFontSize(10);
    obrasSeleccionadas.forEach(o => {
      y = asegurarEspazo(doc, y, 14);
      doc.setFont(undefined, "bold"); doc.text(`• ${o.titulo}${o.autor ? " — " + o.autor : ""}`, 14, y); y += 6;
      doc.setFont(undefined, "normal");
      const lineas = doc.splitTextToSize(o.progreso || "-", 178);
      y = asegurarEspazo(doc, y, lineas.length * 5 + 4);
      doc.text(lineas, 18, y); y += lineas.length * 5 + 4;
    });
    y += 2;
  }
  if (opcions.inicioClase && fila.inicio_clase) {
    y = asegurarEspazo(doc, y, 14);
    doc.setFontSize(11); doc.setFont(undefined, "bold"); doc.text("Inicio da clase", 14, y); y += 7;
    doc.setFontSize(10); doc.setFont(undefined, "normal");
    const lineas = doc.splitTextToSize(fila.inicio_clase, 180);
    y = asegurarEspazo(doc, y, lineas.length * 5);
    doc.text(lineas, 14, y); y += lineas.length * 5 + 6;
  }
  if (opcions.tarefas && fila.tarefas) {
    y = asegurarEspazo(doc, y, 14);
    doc.setFontSize(11); doc.setFont(undefined, "bold"); doc.text("Tarefas", 14, y); y += 7;
    doc.setFontSize(10); doc.setFont(undefined, "normal");
    const lineas = doc.splitTextToSize(fila.tarefas, 180);
    y = asegurarEspazo(doc, y, lineas.length * 5);
    doc.text(lineas, 14, y); y += lineas.length * 5 + 6;
  }
  if (opcions.notas) {
    y = asegurarEspazo(doc, y, 20);
    doc.setFontSize(11); doc.setFont(undefined, "bold"); doc.text("Notas do día", 14, y); y += 8;
    doc.setFontSize(10);
    pesos.forEach(p => {
      y = asegurarEspazo(doc, y, 6);
      const valor = fila[p.key];
      doc.setFont(undefined, "normal");
      doc.text(`${p.label} (${Math.round(p.peso*100)}%):`, 14, y);
      doc.text((valor !== null && valor !== undefined && valor !== "") ? String(valor) : "-", 130, y);
      y += 6;
    });
    if (filaCompleta(fila, pesos)) {
      y += 2;
      doc.setFont(undefined, "bold");
      doc.text(`Media de clase: ${fmt(mediaFila(fila, pesos))}`, 14, y); y += 6;
    }
  }

  const nomeArquivo = `Clase_${(alumno.nome||"alumno").replace(/\s+/g,"_")}_${fila.data||""}.pdf`;
  doc.save(nomeArquivo);
  return nomeArquivo;
}

function trimestreActual() {
  const m = new Date().getMonth() + 1;
  if (m >= 9 && m <= 12) return 1;
  if (m >= 1 && m <= 3) return 2;
  return 3;
}

function exportarInformeSustitutoPDF(anoEscolar, trimestre, detalles) {
  const doc = new window.jspdf.jsPDF();
  cabeceiraPDF(doc, `Informe para substituto — ${trimestre}º trimestre`);
  let y = 48;
  doc.setFontSize(9); doc.setTextColor(90, 114, 144);
  doc.text(`Curso escolar ${anoEscolar} · ${detalles.length} alumnos`, 14, y); y += 9;

  detalles.forEach((d, i) => {
    y = asegurarEspazo(doc, y, 24);
    if (i > 0) {
      doc.setDrawColor(227, 233, 242);
      doc.line(14, y, 196, y); y += 8;
    }
    doc.setTextColor(13, 79, 139); doc.setFontSize(12); doc.setFont(undefined, "bold");
    doc.text(`${d.alumno.nome} ${d.alumno.apelidos || ""}`, 14, y); y += 6;

    doc.setTextColor(10, 37, 64); doc.setFontSize(9.5); doc.setFont(undefined, "normal");
    doc.text(`${d.curso || "-"} · ${labelGrao(d.grao)} · Horario: ${textoHorarios(d.horario)}`, 14, y); y += 5;

    const contactos = [
      d.alumno.telefono_pai ? `Pai: ${d.alumno.telefono_pai}` : null,
      d.alumno.telefono_nai ? `Nai: ${d.alumno.telefono_nai}` : null,
    ].filter(Boolean).join("   ·   ");
    if (contactos) { doc.text(contactos, 14, y); y += 6; } else { y += 2; }

    if (d.repertorio.length) {
      y = asegurarEspazo(doc, y, 8);
      doc.setFont(undefined, "bold"); doc.text("Repertorio actual:", 14, y); y += 5;
      doc.setFont(undefined, "normal");
      d.repertorio.forEach(r => {
        const lineas = doc.splitTextToSize(`• [${r.tipo}] ${r.titulo}${r.autor ? " — " + r.autor : ""}`, 178);
        y = asegurarEspazo(doc, y, lineas.length * 5);
        doc.text(lineas, 16, y); y += lineas.length * 5;
      });
      y += 2;
    }
    if (d.clasesRecentes.length) {
      y = asegurarEspazo(doc, y, 8);
      doc.setFont(undefined, "bold"); doc.text("Últimas clases:", 14, y); y += 5;
      doc.setFont(undefined, "normal");
      d.clasesRecentes.forEach(c => {
        if (c.observacions) {
          const lineas = doc.splitTextToSize(`${formatarDataCurta(c.data)}: ${c.observacions}`, 178);
          y = asegurarEspazo(doc, y, lineas.length * 5);
          doc.text(lineas, 16, y); y += lineas.length * 5;
        }
        c.obras.forEach(o => {
          if (!o.progreso) return;
          const lineas = doc.splitTextToSize(`- ${o.titulo}: ${o.progreso}`, 174);
          y = asegurarEspazo(doc, y, lineas.length * 5);
          doc.text(lineas, 18, y); y += lineas.length * 5;
        });
      });
    }
    y += 6;
  });

  doc.save(`Informe_substituto_${anoEscolar.replace("/","-")}.pdf`);
}

async function xerarInformeSustitutoParaCurso(anoEscolar) {
  const { data, error } = await sb
    .from("matriculas")
    .select("*, alumnos(*), materias(nome, horarios_materia(dia_semana,hora))")
    .eq("curso_escolar", anoEscolar)
    .order("created_at", { ascending: true });
  if (error) { aviso("Erro ao cargar alumnos: " + error.message, "erro"); return; }
  const filas = data
    .filter(m => m.alumnos && m.alumnos.activo !== false)
    .map(m => {
      const materiaViolin = (m.materias || []).find(x => (x.nome||"").toLowerCase().includes("violín"))
        || (m.materias || [])[0] || null;
      return { ...m, horarioViolin: materiaViolin ? materiaViolin.horarios_materia : [] };
    });
  if (!filas.length) { aviso(`Non hai alumnos matriculados en ${anoEscolar}.`, "erro"); return; }

  const trimestre = trimestreActual();
  const detalles = await Promise.all(filas.map(async (m) => {
    const [{ data: repertorio }, { data: clasesRecentes }] = await Promise.all([
      sb.from("repertorio_asignado").select("*, repertorio_xeral(titulo,autor)")
        .eq("matricula_id", m.id).eq("trimestre", trimestre).eq("completada", false).order("tipo"),
      sb.from("clases").select("*, clases_repertorio(*, repertorio_asignado(texto_libre, numero_estudo, tipo, repertorio_xeral(titulo)))")
        .eq("matricula_id", m.id).eq("trimestre", trimestre).eq("falta", false)
        .order("data", { ascending: false }).limit(3),
    ]);
    return {
      alumno: m.alumnos, curso: m.curso, grao: m.grao, horario: m.horarioViolin,
      repertorio: (repertorio||[]).map(r => ({
        tipo: r.tipo, titulo: tituloConNumero(r.repertorio_xeral?.titulo || r.texto_libre, r.numero_estudo, r.tipo), autor: r.repertorio_xeral?.autor,
      })),
      clasesRecentes: (clasesRecentes||[]).map(c => ({
        data: c.data, observacions: c.observacions,
        obras: (c.clases_repertorio||[]).map(cr => ({
          titulo: tituloConNumero(cr.repertorio_asignado?.repertorio_xeral?.titulo || cr.repertorio_asignado?.texto_libre || "?", cr.repertorio_asignado?.numero_estudo, cr.repertorio_asignado?.tipo),
          progreso: cr.progreso,
        })),
      })),
    };
  }));
  exportarInformeSustitutoPDF(anoEscolar, trimestre, detalles);
}

function exportarResumoTrimestralPDF(alumno, matricula, trimestre, datos, opcions) {
  const doc = new window.jspdf.jsPDF();
  cabeceiraPDF(doc, `Resumo do ${trimestre}º trimestre`);
  let y = 48;
  doc.setFontSize(10);
  doc.setFont(undefined, "bold"); doc.text("Alumno:", 14, y);
  doc.setFont(undefined, "normal"); doc.text(`${alumno.nome} ${alumno.apelidos || ""}`, 45, y); y += 7;
  doc.setFont(undefined, "bold"); doc.text("Curso:", 14, y);
  doc.setFont(undefined, "normal"); doc.text(`${matricula.curso || "-"} · ${labelGrao(matricula.grao)} · ${matricula.curso_escolar}`, 45, y); y += 10;

  if (opcions.obraProgreso && datos.obrasAgrupadas.length) {
    y = asegurarEspazo(doc, y, 14);
    doc.setFontSize(12); doc.setFont(undefined, "bold"); doc.text("Repertorio e progreso do trimestre", 14, y); y += 8;
    datos.obrasAgrupadas.forEach(ob => {
      y = asegurarEspazo(doc, y, 10);
      doc.setFontSize(10.5); doc.setFont(undefined, "bold"); doc.text(ob.titulo, 14, y); y += 6;
      ob.entradas.forEach(e => {
        const lineas = doc.splitTextToSize(`${e.data}: ${e.progreso || "-"}`, 176);
        y = asegurarEspazo(doc, y, lineas.length * 5);
        doc.setFontSize(9.5); doc.setFont(undefined, "normal");
        doc.text(lineas, 18, y); y += lineas.length * 5 + 2;
      });
      y += 4;
    });
  }
  if (opcions.inicioClase && datos.inicioClasePorData.length) {
    y = asegurarEspazo(doc, y, 14);
    doc.setFontSize(12); doc.setFont(undefined, "bold"); doc.text("Inicio de clase", 14, y); y += 8;
    datos.inicioClasePorData.forEach(e => {
      const lineas = doc.splitTextToSize(`${e.data}: ${e.texto}`, 178);
      y = asegurarEspazo(doc, y, lineas.length * 5);
      doc.setFontSize(9.5); doc.setFont(undefined, "normal");
      doc.text(lineas, 14, y); y += lineas.length * 5 + 3;
    });
    y += 4;
  }
  if (opcions.tarefas && datos.tarefasPorData.length) {
    y = asegurarEspazo(doc, y, 14);
    doc.setFontSize(12); doc.setFont(undefined, "bold"); doc.text("Tarefas", 14, y); y += 8;
    datos.tarefasPorData.forEach(e => {
      const lineas = doc.splitTextToSize(`${e.data}: ${e.texto}`, 178);
      y = asegurarEspazo(doc, y, lineas.length * 5);
      doc.setFontSize(9.5); doc.setFont(undefined, "normal");
      doc.text(lineas, 14, y); y += lineas.length * 5 + 3;
    });
    y += 4;
  }
  if (opcions.notas) {
    y = asegurarEspazo(doc, y, 26);
    doc.setFontSize(12); doc.setFont(undefined, "bold"); doc.text("Cualificación", 14, y); y += 8;
    doc.setFontSize(10); doc.setFont(undefined, "normal");
    if (datos.cualificacion.alternativa) {
      doc.text("Avaliación non continua (proba única)", 14, y); y += 6;
      doc.setFont(undefined, "bold");
      doc.text(`Nota final: ${fmt(datos.cualificacion.final)}`, 14, y); y += 6;
    } else {
      doc.text(`Clases (${datos.cualificacion.hayAudicion ? "70%" : "100%"}): ${fmt(datos.cualificacion.clases)}`, 14, y); y += 6;
      doc.text(`Audición (30%): ${datos.cualificacion.hayAudicion ? fmt(datos.cualificacion.audicion) : "sen datos"}`, 14, y); y += 6;
      doc.setFont(undefined, "bold");
      doc.text(`Nota final: ${fmt(datos.cualificacion.final)}`, 14, y); y += 6;
    }
    y += 4;
  }
  if (opcions.faltas) {
    y = asegurarEspazo(doc, y, 14);
    doc.setFontSize(12); doc.setFont(undefined, "bold"); doc.text("Faltas", 14, y); y += 8;
    doc.setFontSize(10); doc.setFont(undefined, "normal");
    if (!datos.faltas.length) { doc.text("Sen faltas rexistradas.", 14, y); y += 6; }
    else datos.faltas.forEach(f => {
      y = asegurarEspazo(doc, y, 6);
      doc.text(`${f.data}${f.motivo ? " — " + f.motivo : ""}`, 14, y); y += 6;
    });
  }

  const nomeArquivo = `Resumo_${trimestre}oTrim_${(alumno.nome||"alumno").replace(/\s+/g,"_")}.pdf`;
  doc.save(nomeArquivo);
  return nomeArquivo;
}

