// LOGIN
// ============================================================
const CLAVE_FACEID = "caderno_profesor_faceid";
const bioDispoñible = () => { try { return typeof window.PublicKeyCredential !== "undefined"; } catch (e) { return false; } };

function Login({ onLogged }) {
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [err, setErr] = useState("");
  const [cargando, setCargando] = useState(false);
  const [bioGardado] = useState(() => { try { return bioDispoñible() && !!localStorage.getItem(CLAVE_FACEID); } catch (e) { return false; } });

  async function entrar(e) {
    e.preventDefault();
    setErr(""); setCargando(true);
    const { error } = await sb.auth.signInWithPassword({ email, password: pass });
    setCargando(false);
    if (error) setErr("Email ou contrasinal incorrectos.");
    else onLogged();
  }

  async function entrarBio() {
    setErr("");
    try {
      const gardado = JSON.parse(localStorage.getItem(CLAVE_FACEID));
      const challenge = crypto.getRandomValues(new Uint8Array(32));
      const cred = await navigator.credentials.get({
        publicKey: { challenge, rpId: location.hostname || "localhost", userVerification: "required", timeout: 60000 },
      });
      if (!cred) throw new Error("sen credencial");
      const { error } = await sb.auth.signInWithPassword({ email: gardado.email, password: atob(gardado.p) });
      if (error) throw error;
      onLogged();
    } catch (e) {
      setErr("Non se puido verificar con Face ID / Touch ID. Proba co contrasinal.");
    }
  }

  return (
    <div className="login-shell">
      <div className="login-card">
        <img src={LOGO_CMUS} alt="CMUS Profesional da Coruña" style={{ width: "100%", maxWidth: 260, marginBottom: 18 }} />
        <h1 className="serif" style={{ fontSize: 22, margin: "0 0 2px" }}>Caderno do Profesor</h1>
        <p style={{ color: "var(--sepia)", fontSize: 13, marginTop: 0 }}>CMUS Profesional da Coruña · Prof. Jorge Montes</p>
        <form onSubmit={entrar}>
          <Campo label="Email" type="email" value={email} onChange={e=>setEmail(e.target.value)} required />
          <Campo label="Contrasinal" type="password" value={pass} onChange={e=>setPass(e.target.value)} required />
          {err && <div className="err">{err}</div>}
          <button className="btn btn-primary btn-block" style={{ marginTop: 16 }} disabled={cargando}>
            {cargando ? "Entrando…" : "Entrar"}
          </button>
        </form>
        {bioGardado && <button type="button" className="btn-faceid" onClick={entrarBio}>🔒 Entrar con Face ID / Touch ID</button>}
      </div>
    </div>
  );
}

// ============================================================
// Selector de horarios: día (Luns-Venres) + hora (10:00-21:00, cada 30 min)
// horarios = [{ dia_semana, hora }]
// ============================================================
// Lista de pianistas acompañantes (xestionada en Axustes; evita duplicados por erros de escritura)
function usePianistas() {
  const [pianistas, setPianistas] = useState([]);
  useEffect(() => {
    (async () => {
      const { data } = await sb.from("pianistas").select("nome").order("nome");
      setPianistas((data || []).map(p => p.nome));
    })();
  }, []);
  return pianistas;
}

function SelectorPianista({ valor, onChange }) {
  const pianistas = usePianistas();
  const lista = valor && !pianistas.includes(valor) ? [...pianistas, valor] : pianistas;
  return (
    <select className="field" value={valor || ""} onChange={e=>onChange(e.target.value)}>
      <option value="">— Sen pianista —</option>
      {lista.map(p => <option key={p} value={p}>{p}</option>)}
    </select>
  );
}

function EditorHorarios({ horarios, onChange }) {
  function cambiarFila(i, campo, valor) {
    const copia = horarios.slice();
    copia[i] = { ...copia[i], [campo]: valor };
    onChange(copia);
  }
  function engadirFila() {
    onChange([...horarios, { dia_semana: "Luns", hora: "17:00" }]);
  }
  function quitarFila(i) {
    onChange(horarios.filter((_, idx) => idx !== i));
  }
  return (
    <div>
      {horarios.map((h, i) => (
        <div key={i} style={{ display: "flex", gap: 6, marginBottom: 6, alignItems: "center" }}>
          <select className="field" style={{ flex: 1 }} value={h.dia_semana} onChange={e=>cambiarFila(i,"dia_semana",e.target.value)}>
            {DIAS_SEMANA.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
          <select className="field" style={{ flex: 1 }} value={(h.hora||"").slice(0,5)} onChange={e=>cambiarFila(i,"hora",e.target.value)}>
            {HORAS_DISPONIBLES.map(h2 => <option key={h2} value={h2}>{h2}</option>)}
          </select>
          <button type="button" className="btn btn-danger" style={{ padding: "6px 10px" }} onClick={()=>quitarFila(i)}>✕</button>
        </div>
      ))}
      <button type="button" className="btn" style={{ fontSize: 12.5, padding: "6px 10px" }} onClick={engadirFila}>+ Engadir horario</button>
    </div>
  );
}

// ============================================================
// FORM alumno + matrícula (crear)
// ============================================================
function FormNovoAlumno({ anoEscolar, onClose, onCreated }) {
  const [f, setF] = useState({
    nome: "", apelidos: "", expediente: "", data_nacemento: "",
    direccion: "", cp: "", poboacion: "",
    telefono_alumno: "", telefono_pai: "", telefono_nai: "",
    email_alumno: "", nome_pai: "", email_pai: "", nome_nai: "", email_nai: "", observacions: "",
    grao: "elemental", curso: "",
    profesor_titor: "Jorge Montes", pianista_acompanante: "",
    horarios: [{ dia_semana: "Luns", hora: "17:00" }],
  });
  const [gardando, setGardando] = useState(false);
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });

  async function gardar(e) {
    e.preventDefault();
    setGardando(true);
    const { data: alumno, error: e1 } = await sb.from("alumnos").insert({
      nome: f.nome, apelidos: f.apelidos, expediente: f.expediente,
      data_nacemento: f.data_nacemento || null, direccion: f.direccion, cp: f.cp, poboacion: f.poboacion,
      telefono_alumno: f.telefono_alumno, telefono_pai: f.telefono_pai, telefono_nai: f.telefono_nai,
      email_alumno: f.email_alumno, nome_pai: f.nome_pai, email_pai: f.email_pai,
      nome_nai: f.nome_nai, email_nai: f.email_nai,
      observacions: f.observacions,
    }).select().single();
    if (e1) { aviso("Erro ao crear alumno: " + e1.message, "erro"); setGardando(false); return; }

    const { data: matricula, error: e2 } = await sb.from("matriculas").insert({
      alumno_id: alumno.id, curso_escolar: anoEscolar, grao: f.grao, curso: f.curso,
    }).select().single();
    if (e2) { aviso("Erro ao crear matrícula: " + e2.message, "erro"); setGardando(false); return; }

    const { data: materia, error: e3 } = await sb.from("materias").insert({
      matricula_id: matricula.id, nome: "Violín",
      profesor_titor: f.profesor_titor, pianista_acompanante: f.pianista_acompanante,
    }).select().single();
    if (e3) { aviso("Erro ao crear materia: " + e3.message, "erro"); setGardando(false); return; }

    if (f.horarios.length) {
      const { error: e4 } = await sb.from("horarios_materia").insert(
        f.horarios.map(h => ({ materia_id: materia.id, dia_semana: h.dia_semana, hora: h.hora }))
      );
      if (e4) { aviso("Erro ao crear horarios: " + e4.message, "erro"); setGardando(false); return; }
    }
    setGardando(false);
    onCreated();
  }

  return (
    <Modal title="Novo alumno" onClose={onClose}>
      <form onSubmit={gardar}>
        <div className="grid2">
          <Campo label="Nome" value={f.nome} onChange={set("nome")} required />
          <Campo label="Apelidos" value={f.apelidos} onChange={set("apelidos")} />
        </div>
        <div className="grid2">
          <div>
            <label>Grao</label>
            <select className="field" value={f.grao} onChange={set("grao")}>
              <option value="elemental">Elemental (GE)</option>
              <option value="profesional">Profesional (GP)</option>
            </select>
          </div>
          <Campo label="Curso (p.ex. 3º)" value={f.curso} onChange={set("curso")} />
        </div>
        <div className="field-note">Matrícula para o curso escolar {anoEscolar}</div>

        <label>Profesor titor (Violín)</label>
        <input type="text" value={f.profesor_titor} onChange={set("profesor_titor")} />
        <label>Pianista acompañante</label>
        <SelectorPianista valor={f.pianista_acompanante} onChange={v=>setF({...f, pianista_acompanante: v})} />
        <label>Horario de Violín</label>
        <EditorHorarios horarios={f.horarios} onChange={(h)=>setF({...f, horarios: h})} />

        <div className="grid2">
          <Campo label="Expediente" value={f.expediente} onChange={set("expediente")} />
          <Campo label="Data nacemento" type="date" value={f.data_nacemento} onChange={e=>{ if (e.target.value) setF({...f, data_nacemento: e.target.value}); }} />
        </div>
        <Campo label="Dirección" value={f.direccion} onChange={set("direccion")} />
        <div className="grid2">
          <Campo label="C.P." value={f.cp} onChange={set("cp")} />
          <Campo label="Poboación" value={f.poboacion} onChange={set("poboacion")} />
        </div>
        <div className="grid2">
          <Campo label="Teléfono alumno" type="tel" value={f.telefono_alumno} onChange={set("telefono_alumno")} />
          <Campo label="Email alumno" type="email" value={f.email_alumno} onChange={set("email_alumno")} />
        </div>
        <Campo label="Nome do pai" value={f.nome_pai} onChange={set("nome_pai")} />
        <div className="grid2">
          <Campo label="Teléfono pai" type="tel" value={f.telefono_pai} onChange={set("telefono_pai")} />
          <Campo label="Email pai" type="email" value={f.email_pai} onChange={set("email_pai")} />
        </div>
        <Campo label="Nome da nai" value={f.nome_nai} onChange={set("nome_nai")} />
        <div className="grid2">
          <Campo label="Teléfono nai" type="tel" value={f.telefono_nai} onChange={set("telefono_nai")} />
          <Campo label="Email nai" type="email" value={f.email_nai} onChange={set("email_nai")} />
        </div>
        <label>Observacións</label>
        <textarea value={f.observacions} onChange={set("observacions")}></textarea>

        <div className="row-actions">
          <button type="button" className="btn" onClick={onClose}>Cancelar</button>
          <button className="btn btn-primary" disabled={gardando}>{gardando ? "Gardando…" : "Crear alumno"}</button>
        </div>
      </form>
    </Modal>
  );
}

