const DISPOSITIVO_TACTIL = (() => {
  try { return !!(window.matchMedia && window.matchMedia("(pointer: coarse)").matches); }
  catch (e) { return false; }
})();

function FilaEliminable({ id, abertaId, onAbrirSwipe, onEliminar, children, className, anchoBoton }) {
  const ANCHO = anchoBoton || 84;
  const [offset, setOffset] = useState(0);
  const [arrastrando, setArrastrando] = useState(false);
  const inicioRef = useRef({ x: 0, offsetInicial: 0, moveuse: false });
  const aberta = abertaId === id;
  useEffect(() => { if (!aberta) setOffset(0); }, [aberta]);

  if (!DISPOSITIVO_TACTIL) {
    return (
      <div style={{ display: "flex", alignItems: "stretch", gap: 8, marginBottom: 9 }}>
        <div style={{ flex: 1, minWidth: 0 }}>{children}</div>
        <button type="button" className="btn btn-danger" style={{ padding: "4px 9px", flexShrink: 0, alignSelf: "center" }}
          onClick={(e)=>{ e.stopPropagation(); onEliminar(); }}>✕</button>
      </div>
    );
  }

  function onPointerDown(e) { inicioRef.current = { x: e.clientX, offsetInicial: offset, moveuse: false }; setArrastrando(true); }
  function onPointerMove(e) {
    if (!arrastrando) return;
    const dx = e.clientX - inicioRef.current.x;
    if (Math.abs(dx) > 5) inicioRef.current.moveuse = true;
    setOffset(Math.max(-ANCHO, Math.min(0, inicioRef.current.offsetInicial + dx)));
  }
  function rematarArrastre() {
    if (!arrastrando) return;
    setArrastrando(false);
    if (offset < -ANCHO/2) { setOffset(-ANCHO); onAbrirSwipe(id); }
    else { setOffset(0); onAbrirSwipe(null); }
  }
  function clicCaptura(e) {
    if (inicioRef.current.moveuse) { e.stopPropagation(); return; }
    if (offset !== 0) { setOffset(0); onAbrirSwipe(null); e.stopPropagation(); }
  }

  return (
    <div className="swipe-wrap">
      <div className="swipe-borrar" style={{ width: ANCHO }} onClick={()=>onEliminar()}>Eliminar</div>
      <div className={className}
        style={{ transform: `translateX(${offset}px)`, transition: arrastrando ? "none" : "transform .18s ease",
          touchAction: "pan-y", position: "relative", zIndex: 1, background: "#fff" }}
        onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={rematarArrastre} onPointerCancel={rematarArrastre}
        onClickCapture={clicCaptura}>
        {children}
      </div>
    </div>
  );
}

function FilaAlumno({ m, abertaId, onAbrirSwipe, onAbrir, onEliminar }) {
  return (
    <FilaEliminable id={m.id} abertaId={abertaId} onAbrirSwipe={onAbrirSwipe} onEliminar={()=>onEliminar(m)} className="alumno-row-inner">
      <div className="alumno-row" style={{ marginBottom: 0 }} onClick={() => onAbrir(m)}>
        {m.fotoUrl
          ? <img src={m.fotoUrl} alt="" style={{ width: 38, height: 38, borderRadius: "50%", objectFit: "cover", flexShrink: 0 }} />
          : <div className="avatar">{(m.alumnos.nome||"?")[0].toUpperCase()}</div>}
        <div className="info">
          <div className="nome">{m.alumnos.nome} {m.alumnos.apelidos}</div>
          <div className="meta">{textoHorarios(m.horarioViolin)}</div>
        </div>
        <span className={"tag" + (m.grao === "profesional" ? " gp" : "")}>
          {m.curso ? `${m.curso} ` : ""}{m.grao === "profesional" ? "G.P." : "G.E."}
        </span>
      </div>
    </FilaEliminable>
  );
}

function ListaAlumnos({ anoEscolar, onAbrir }) {
  const [filas, setFilas] = useState(null);
  const [verArquivados, setVerArquivados] = useState(false);
  const [busca, setBusca] = useState("");
  const [mostrarForm, setMostrarForm] = useState(false);
  const [abertaId, setAbertaId] = useState(null);

  async function cargar() {
    const { data, error } = await sb
      .from("matriculas")
      .select("*, alumnos(*), materias(nome, horarios_materia(dia_semana,hora))")
      .eq("curso_escolar", anoEscolar)
      .order("created_at", { ascending: true });
    if (error) { aviso("Erro ao cargar alumnos: " + error.message, "erro"); return; }
    const procesadas = data
      .filter(m => m.alumnos)
      .map(m => {
        const materiaViolin = (m.materias || []).find(x => (x.nome||"").toLowerCase().includes("violín"))
          || (m.materias || [])[0] || null;
        const horarioViolin = materiaViolin ? materiaViolin.horarios_materia : [];
        return { ...m, horarioViolin };
      })
      .sort((a,b) => claveOrdeHorario(a.horarioViolin) - claveOrdeHorario(b.horarioViolin));
    await Promise.all(procesadas.map(async m => {
      if (!m.alumnos.foto_path) return;
      m.fotoUrl = await obterUrlFotoCacheada(m.alumnos.foto_path);
    }));
    setFilas(procesadas);
  }
  useEffect(() => { setFilas(null); cargar(); }, [anoEscolar]);

  const filtradas = useMemo(() => {
    if (!filas) return [];
    const base = filas.filter(m => verArquivados ? m.alumnos.activo === false : m.alumnos.activo !== false);
    const q = busca.trim().toLowerCase();
    if (!q) return base;
    return base.filter(m => `${m.alumnos.nome} ${m.alumnos.apelidos||""}`.toLowerCase().includes(q));
  }, [filas, busca, verArquivados]);
  const cantosArquivados = filas ? filas.filter(m => m.alumnos.activo === false).length : 0;

  async function eliminarAlumno(m) {
    setAbertaId(null);
    if (!confirm(`Eliminar a ${m.alumnos.nome} ${m.alumnos.apelidos||""}? Bórranse TODOS os seus datos (clases, repertorio, cualificacións, titorías...) de TODOS os cursos escolares. Esta acción non se pode desfacer.`)) return;
    const { error } = await sb.from("alumnos").delete().eq("id", m.alumnos.id);
    if (error) { aviso(error.message, "erro"); return; }
    cargar();
  }

  return (
    <div className="wrap">
      <div className="toolbar">
        <input className="search" type="text" placeholder="Buscar alumno…" value={busca} onChange={e=>setBusca(e.target.value)} />
        {cantosArquivados > 0 && (
          <button className="btn" style={{ fontSize: 12 }} onClick={()=>setVerArquivados(v=>!v)}>
            {verArquivados ? "← Activos" : `Arquivados (${cantosArquivados})`}
          </button>
        )}
      </div>

      {filas === null && <div className="empty">Cargando…</div>}
      {filas !== null && filtradas.length === 0 && (
        <div className="empty">Non hai alumnos matriculados en {anoEscolar}.<br/>Toca “+” para engadir o primeiro.</div>
      )}
      {filtradas.map(m => (
        <FilaAlumno key={m.id} m={m} abertaId={abertaId} onAbrirSwipe={setAbertaId} onAbrir={onAbrir} onEliminar={eliminarAlumno} />
      ))}

      <button className="fab" onClick={() => setMostrarForm(true)} aria-label="Engadir alumno">+</button>
      {mostrarForm && (
        <FormNovoAlumno
          anoEscolar={anoEscolar}
          onClose={() => setMostrarForm(false)}
          onCreated={() => { setMostrarForm(false); cargar(); }}
        />
      )}
    </div>
  );
}

