function FotoAlumno({ alumno, onAtualizado }) {
  const [url, setUrl] = useState(null);
  const [subindo, setSubindo] = useState(false);
  const inputRef = useRef(null);

  async function cargarUrl() {
    if (!alumno.foto_path) { setUrl(null); return; }
    const signedUrl = await obterUrlFotoCacheada(alumno.foto_path);
    if (signedUrl) setUrl(signedUrl);
  }
  useEffect(() => { cargarUrl(); }, [alumno.foto_path]);

  async function subir(e) {
    const ficheiro = e.target.files[0];
    if (!ficheiro) return;
    setSubindo(true);
    const reducida = await redimensionarImaxe(ficheiro, 400);
    const path = `${alumno.id}.jpg`;
    const { error: eUp } = await sb.storage.from("fotos-alumnos").upload(path, reducida, { upsert: true, contentType: "image/jpeg" });
    if (eUp) { aviso("Erro ao subir a foto: " + eUp.message, "erro"); setSubindo(false); return; }
    delete cacheUrlsFotos[path];
    await gardarSeguro(sb.from("alumnos").update({ foto_path: path }).eq("id", alumno.id), "alumnos");
    setSubindo(false);
    onAtualizado();
  }

  async function quitar() {
    if (!confirm("Quitar a foto do alumno?")) return;
    if (alumno.foto_path) { await sb.storage.from("fotos-alumnos").remove([alumno.foto_path]); delete cacheUrlsFotos[alumno.foto_path]; }
    await gardarSeguro(sb.from("alumnos").update({ foto_path: null }).eq("id", alumno.id), "alumnos");
    onAtualizado();
  }

  return (
    <div style={{ float: "left", marginRight: 14, textAlign: "center" }}>
      <div style={{
        width: 84, height: 84, borderRadius: "50%", overflow: "hidden", background: "var(--marfil)",
        border: "1.5px solid var(--crema)", display: "flex", alignItems: "center", justifyContent: "center",
      }}>
        {url ? <img src={url} alt="Foto do alumno" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
             : <span style={{ fontSize: 26 }}>📷</span>}
      </div>
      <input ref={inputRef} type="file" accept="image/*" capture="environment" style={{ display: "none" }} onChange={subir} />
      <div>
        <button type="button" className="btn btn-ghost" style={{ fontSize: 11, padding: "3px 4px", marginTop: 4 }}
          onClick={()=>inputRef.current.click()} disabled={subindo}>
          {subindo ? "Subindo…" : (url ? "Cambiar" : "Facer foto")}
        </button>
        {url && <button type="button" className="btn btn-ghost" style={{ fontSize: 11, padding: "3px 4px", color: "var(--rojo)" }} onClick={quitar}>Quitar</button>}
      </div>
    </div>
  );
}

function TabFicha({ alumno, matricula, cualificacions, materias, onAtualizado }) {
  const [editando, setEditando] = useState(false);
  const [f, setF] = useState(() => ({ ...alumno, curso: matricula.curso, grao: matricula.grao }));
  useEffect(() => setF({ ...alumno, curso: matricula.curso, grao: matricula.grao }), [alumno, matricula]);
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });

  async function gardar() {
    const ok1 = await gardarSeguro(sb.from("alumnos").update({
      nome: f.nome, apelidos: f.apelidos, expediente: f.expediente,
      data_nacemento: f.data_nacemento || null, direccion: f.direccion, cp: f.cp, poboacion: f.poboacion,
      telefono_alumno: f.telefono_alumno, telefono_pai: f.telefono_pai, telefono_nai: f.telefono_nai,
      email_alumno: f.email_alumno, nome_pai: f.nome_pai, email_pai: f.email_pai,
      nome_nai: f.nome_nai, email_nai: f.email_nai,
      observacions: f.observacions,
    }).eq("id", alumno.id), "alumno");
    const ok2 = await gardarSeguro(sb.from("matriculas").update({
      curso: f.curso, grao: f.grao,
    }).eq("id", matricula.id), "matrícula");
    if (!ok1 || !ok2) return;
    setEditando(false);
    onAtualizado();
  }

  if (editando) {
    return (
      <div className="card">
        <div className="grid2">
          <Campo label="Curso (p.ex. 3º)" value={f.curso||""} onChange={set("curso")} />
          <div>
            <label>Grao</label>
            <select className="field" value={f.grao||"elemental"} onChange={set("grao")}>
              <option value="elemental">Elemental (GE)</option>
              <option value="profesional">Profesional (GP)</option>
            </select>
          </div>
        </div>
        <div className="grid2">
          <Campo label="Nome" value={f.nome||""} onChange={set("nome")} />
          <Campo label="Apelidos" value={f.apelidos||""} onChange={set("apelidos")} />
        </div>
        <div className="grid2">
          <Campo label="Expediente" value={f.expediente||""} onChange={set("expediente")} />
          <Campo label="Data nacemento" type="date" value={f.data_nacemento||""} onChange={e=>{ if (e.target.value) setF({...f, data_nacemento: e.target.value}); }} />
        </div>
        <Campo label="Dirección" value={f.direccion||""} onChange={set("direccion")} />
        <div className="grid2">
          <Campo label="C.P." value={f.cp||""} onChange={set("cp")} />
          <Campo label="Poboación" value={f.poboacion||""} onChange={set("poboacion")} />
        </div>
        <div className="grid2">
          <Campo label="Teléfono alumno" value={f.telefono_alumno||""} onChange={set("telefono_alumno")} />
          <Campo label="Email alumno" value={f.email_alumno||""} onChange={set("email_alumno")} />
        </div>
        <Campo label="Nome do pai" value={f.nome_pai||""} onChange={set("nome_pai")} />
        <div className="grid2">
          <Campo label="Teléfono pai" value={f.telefono_pai||""} onChange={set("telefono_pai")} />
          <Campo label="Email pai" value={f.email_pai||""} onChange={set("email_pai")} />
        </div>
        <Campo label="Nome da nai" value={f.nome_nai||""} onChange={set("nome_nai")} />
        <div className="grid2">
          <Campo label="Teléfono nai" value={f.telefono_nai||""} onChange={set("telefono_nai")} />
          <Campo label="Email nai" value={f.email_nai||""} onChange={set("email_nai")} />
        </div>
        <label>Observacións</label>
        <textarea value={f.observacions||""} onChange={set("observacions")}></textarea>
        <div className="row-actions">
          <button className="btn" onClick={() => { setEditando(false); setF({ ...alumno, curso: matricula.curso, grao: matricula.grao }); }}>Cancelar</button>
          <button className="btn btn-primary" onClick={gardar}>Gardar cambios</button>
        </div>
      </div>
    );
  }

  const Linea = ({ label, valor }) => (
    <div style={{ display: "flex", padding: "6px 0", borderBottom: "1px solid var(--crema)", fontSize: 14 }}>
      <div style={{ width: 140, color: "var(--sepia)", fontWeight: 600, fontSize: 12.5 }}>{label}</div>
      <div style={{ flex: 1 }}>{valor || "—"}</div>
    </div>
  );

  return (
    <div>
      <div className="card">
        <img src={LOGO_CMUS} alt="CMUS" style={{ float: "right", marginLeft: 10, width: 130, height: "auto" }} />
        <FotoAlumno alumno={alumno} onAtualizado={onAtualizado} />
        <h3 className="serif" style={{ margin: "0 0 4px" }}>{alumno.nome} {alumno.apelidos}</h3>
        <span className={"tag" + (matricula.grao === "profesional" ? " gp" : "")}>
          {matricula.grao === "profesional" ? "Grao Profesional" : "Grao Elemental"}
        </span>{" "}
        {alumno.activo === false && <span className="tag" style={{ background: "#eee", color: "var(--sepia)" }}>Arquivado</span>}{" "}
        <span className="tag">{matricula.curso || "—"}</span>
        <div style={{ marginTop: 12, clear: "both" }}>
          <Linea label="Expediente" valor={alumno.expediente} />
          <Linea label="Data nacemento" valor={alumno.data_nacemento ? `${formatarDataCurta(alumno.data_nacemento)}` : null} />
          <Linea label="Idade" valor={calcularIdade(alumno.data_nacemento) !== null ? `${calcularIdade(alumno.data_nacemento)} anos` : null} />
          <Linea label="Dirección" valor={`${alumno.direccion||""} ${alumno.cp||""} ${alumno.poboacion||""}`.trim()} />
          <Linea label="Tfno. alumno" valor={alumno.telefono_alumno} />
          <Linea label="Email alumno" valor={alumno.email_alumno} />
          <Linea label="Nome do pai" valor={alumno.nome_pai} />
          <Linea label="Tfno. pai" valor={alumno.telefono_pai} />
          <Linea label="Email pai" valor={alumno.email_pai} />
          <Linea label="Nome da nai" valor={alumno.nome_nai} />
          <Linea label="Tfno. nai" valor={alumno.telefono_nai} />
          <Linea label="Email nai" valor={alumno.email_nai} />
          <Linea label="Observacións" valor={alumno.observacions} />
        </div>
        <div className="row-actions">
          <button className="btn" onClick={() => setEditando(true)}>Editar datos</button>
          <button className="btn" onClick={async () => {
            const arquivando = alumno.activo !== false;
            if (!confirm(arquivando
              ? `Arquivar a ${alumno.nome}? Deixará de aparecer na lista de alumnos, pero gárdase todo o seu historial e podes recuperalo cando queiras.`
              : `Reactivar a ${alumno.nome}? Volverá aparecer na lista de alumnos.`)) return;
            const ok = await gardarSeguro(sb.from("alumnos").update({ activo: !arquivando }).eq("id", alumno.id), "alumno");
            if (ok) onAtualizado();
          }}>{alumno.activo === false ? "Reactivar alumno" : "Arquivar alumno"}</button>
          <button className="btn btn-primary" onClick={() => exportarFichaPDF(alumno, matricula, cualificacions, materias)}>
            Exportar PDF
          </button>
        </div>
      </div>
    </div>
  );
}

// ============================================================
// TAB: Materias (cuadro con horario, titor, pianista e notas por trimestre)
// ============================================================
function notaClass(n) {
  if (n === null || n === undefined || n === "") return "";
  return Number(n) < 5 ? "nota-baixa" : "nota-alta";
}

function TabMateriaFila({ materia, expandida, onToggleExpandir, onCambio }) {
  const [notas, setNotas] = useState({
    nota_1: materia.nota_1 ?? "", nota_2: materia.nota_2 ?? "", nota_3: materia.nota_3 ?? "",
  });
  const [f, setF] = useState({
    nome: materia.nome, profesor_titor: materia.profesor_titor || "",
    pianista_acompanante: materia.pianista_acompanante || "",
  });
  const [horarios, setHorarios] = useState(materia.horarios || []);

  function cambiarNota(campo, valor) { setNotas(prev => ({ ...prev, [campo]: valor })); }
  function cambiarCampo(campo, valor) { setF(prev => ({ ...prev, [campo]: valor })); }

  async function gardarNotas() {
    await gardarSeguro(sb.from("materias").update({
      nota_1: notas.nota_1 === "" ? null : notas.nota_1,
      nota_2: notas.nota_2 === "" ? null : notas.nota_2,
      nota_3: notas.nota_3 === "" ? null : notas.nota_3,
    }).eq("id", materia.id), "notas de materia");
  }

  async function gardarEdicion() {
    await gardarSeguro(sb.from("materias").update({
      nome: f.nome, profesor_titor: f.profesor_titor, pianista_acompanante: f.pianista_acompanante,
    }).eq("id", materia.id), "materia");
    await gardarSeguro(sb.from("horarios_materia").delete().eq("materia_id", materia.id), "horarios_materia");
    if (horarios.length) {
      await gardarSeguro(sb.from("horarios_materia").insert(horarios.map(h => ({ materia_id: materia.id, dia_semana: h.dia_semana, hora: h.hora }))), "horarios_materia");
    }
    onCambio();
  }

  async function eliminar() {
    if (!confirm(`Eliminar a materia "${materia.nome}"?`)) return;
    await gardarSeguro(sb.from("materias").delete().eq("id", materia.id), "materias");
    onCambio();
  }

  return (
    <React.Fragment>
      <tr>
        <td style={{ fontWeight: 600 }}>{materia.nome}</td>
        <td>{materia.profesor_titor || "—"}</td>
        <td>{materia.pianista_acompanante || "—"}</td>
        <td>
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ fontSize: 12.5, whiteSpace: "nowrap" }}>{textoHorarios(materia.horarios)}</span>
            <button type="button" className="btn btn-ghost" style={{ padding: "3px 6px", fontSize: 11.5 }} onClick={onToggleExpandir}>
              {expandida ? "Pechar" : "Editar"}
            </button>
          </div>
        </td>
        {[1,2,3].map(t => (
          <td key={t}>
            <input type="number" step="0.1" min="0" max="10" className={notaClass(notas["nota_"+t])}
              value={notas["nota_"+t]} onChange={e=>cambiarNota("nota_"+t, e.target.value)} onBlur={gardarNotas} />
          </td>
        ))}
      </tr>
      {expandida && (
        <tr>
          <td colSpan={7} style={{ background: "var(--marfil)" }}>
            <div style={{ padding: "14px 6px" }}>
              <div className="grid2">
                <div>
                  <label>Materia</label>
                  <input type="text" value={f.nome} onChange={e=>cambiarCampo("nome", e.target.value)} />
                </div>
                <div>
                  <label>Profesor titor</label>
                  <input type="text" value={f.profesor_titor} onChange={e=>cambiarCampo("profesor_titor", e.target.value)} />
                </div>
              </div>
              <label>Pianista acompañante</label>
              <SelectorPianista valor={f.pianista_acompanante} onChange={v=>cambiarCampo("pianista_acompanante", v)} />
              <label>Horarios</label>
              <EditorHorarios horarios={horarios} onChange={setHorarios} />
              <div className="row-actions">
                <button className="btn btn-primary" style={{ fontSize: 12.5, padding: "6px 12px" }} onClick={gardarEdicion}>Gardar cambios</button>
                <button className="btn btn-danger" style={{ fontSize: 12.5, padding: "6px 12px" }} onClick={eliminar}>Eliminar materia</button>
              </div>
            </div>
          </td>
        </tr>
      )}
    </React.Fragment>
  );
}

function TabMaterias({ matriculaId, onCambio }) {
  const [materias, setMaterias] = useState(null);
  const [expandidaId, setExpandidaId] = useState(null);
  const [mostrarNova, setMostrarNova] = useState(false);
  const [nova, setNova] = useState({ nome: "", profesor_titor: "", pianista_acompanante: "", horarios: [{ dia_semana: "Luns", hora: "17:00" }] });

  async function cargar() {
    const { data, error } = await sb.from("materias").select("*, horarios_materia(*)").eq("matricula_id", matriculaId);
    if (error) { aviso(error.message, "erro"); return; }
    setMaterias(data.map(m => ({ ...m, horarios: m.horarios_materia })));
    onCambio && onCambio();
  }
  useEffect(() => { cargar(); }, [matriculaId]);

  async function engadirMateria(e) {
    e.preventDefault();
    const { data: materia, error: e1 } = await sb.from("materias").insert({
      matricula_id: matriculaId, nome: nova.nome, profesor_titor: nova.profesor_titor, pianista_acompanante: nova.pianista_acompanante,
    }).select().single();
    if (e1) { aviso(e1.message, "erro"); return; }
    if (nova.horarios.length) {
      await gardarSeguro(sb.from("horarios_materia").insert(nova.horarios.map(h => ({ materia_id: materia.id, dia_semana: h.dia_semana, hora: h.hora }))), "horarios_materia");
    }
    setMostrarNova(false);
    setNova({ nome: "", profesor_titor: "", pianista_acompanante: "", horarios: [{ dia_semana: "Luns", hora: "17:00" }] });
    cargar();
  }

  if (materias === null) return <div className="empty">Cargando…</div>;
  return (
    <div>
      <div className="table-scroll card" style={{ padding: 0 }}>
        <table className="grid">
          <thead>
            <tr>
              <th>Materia</th><th>Titor</th><th>Pianista acomp.</th><th>Horario</th>
              <th>1ª Aval.</th><th>2ª Aval.</th><th>3ª Aval.</th>
            </tr>
          </thead>
          <tbody>
            {materias.map(m => (
              <TabMateriaFila key={m.id} materia={m}
                expandida={expandidaId === m.id}
                onToggleExpandir={() => setExpandidaId(expandidaId === m.id ? null : m.id)}
                onCambio={() => { setExpandidaId(null); cargar(); }} />
            ))}
          </tbody>
        </table>
      </div>

      {mostrarNova ? (
        <div className="card">
          <h3 className="serif" style={{ marginTop: 0, fontSize: 16 }}>Nova materia</h3>
          <form onSubmit={engadirMateria}>
            <Campo label="Materia" value={nova.nome} onChange={e=>setNova({...nova,nome:e.target.value})} required />
            <Campo label="Profesor titor" value={nova.profesor_titor} onChange={e=>setNova({...nova,profesor_titor:e.target.value})} />
            <label>Pianista acompañante</label>
            <SelectorPianista valor={nova.pianista_acompanante} onChange={v=>setNova({...nova, pianista_acompanante: v})} />
            <label>Horarios</label>
            <EditorHorarios horarios={nova.horarios} onChange={(h)=>setNova({...nova, horarios: h})} />
            <div className="row-actions">
              <button type="button" className="btn" onClick={()=>setMostrarNova(false)}>Cancelar</button>
              <button className="btn btn-primary">Engadir materia</button>
            </div>
          </form>
        </div>
      ) : (
        <button className="btn" style={{ marginTop: 10 }} onClick={()=>setMostrarNova(true)}>+ Engadir materia</button>
      )}
    </div>
  );
}

// ============================================================
// REPERTORIO — catálogo xeral e repertorio asignado por alumno
// ============================================================
// Redimensiona/comprime unha imaxe no propio navegador antes de subila (evita fotos de 3-5 MB dun móbil)
function redimensionarImaxe(ficheiro, ladoMax) {
  return new Promise((resolve) => {
    const img = new Image();
    const url = URL.createObjectURL(ficheiro);
    img.onload = () => {
      let { width, height } = img;
      if (width > ladoMax || height > ladoMax) {
        if (width > height) { height = Math.round(height * ladoMax / width); width = ladoMax; }
        else { width = Math.round(width * ladoMax / height); height = ladoMax; }
      }
      const canvas = document.createElement("canvas");
      canvas.width = width; canvas.height = height;
      canvas.getContext("2d").drawImage(img, 0, 0, width, height);
      URL.revokeObjectURL(url);
      canvas.toBlob((blob) => resolve(blob || ficheiro), "image/jpeg", 0.82);
    };
    img.onerror = () => resolve(ficheiro);
    img.src = url;
  });
}

// Caché en memoria de URLs firmadas (evita pedila outra vez cada vez que se recarga a lista)
const cacheUrlsFotos = {};
async function obterUrlFotoCacheada(path) {
  if (!path) return null;
  const agora = Date.now();
  const gardada = cacheUrlsFotos[path];
  if (gardada && gardada.expira > agora) return gardada.url;
  const { data, error } = await sb.storage.from("fotos-alumnos").createSignedUrl(path, 3600);
  if (error || !data) return null;
  cacheUrlsFotos[path] = { url: data.signedUrl, expira: agora + 3500 * 1000 };
  return data.signedUrl;
}

function generarUUID() {
  if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0, v = c === "x" ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
// Executa unha mutación en Supabase avisando se falla (antes fallaban en silencio)
// Sistema de avisos discretos (non bloquean coma alert())
const avisoOyentes = [];
function aviso(texto, tipo) {
  avisoOyentes.forEach(fn => fn({ texto, tipo: tipo || "info", id: Date.now() + Math.random() }));
}
function Avisos() {
  const [lista, setLista] = useState([]);
  useEffect(() => {
    const engadir = (a) => {
      setLista(l => [...l, a]);
      setTimeout(() => setLista(l => l.filter(x => x.id !== a.id)), a.tipo === "erro" ? 6000 : 2200);
    };
    avisoOyentes.push(engadir);
    return () => { const i = avisoOyentes.indexOf(engadir); if (i >= 0) avisoOyentes.splice(i, 1); };
  }, []);
  if (!lista.length) return null;
  return (
    <div className="avisos">
      {lista.map(a => (
        <div key={a.id} className={"aviso " + (a.tipo === "erro" ? "aviso-erro" : a.tipo === "ok" ? "aviso-ok" : "")}>
          {a.texto}
        </div>
      ))}
    </div>
  );
}

async function gardarSeguro(consulta, contexto) {
  try {
    const { error } = await consulta;
    if (error) {
      aviso(`Non se puido gardar${contexto ? " (" + contexto + ")" : ""}: ` + error.message, "erro");
      return false;
    }
    aviso("Gardado", "ok");
    return true;
  } catch (e) {
    aviso(`Non se puido gardar${contexto ? " (" + contexto + ")" : ""}: ` + (e.message || e), "erro");
    return false;
  }
}

function urlPdfRepertorio(path) {
  if (!path) return null;
  return sb.storage.from("repertorio").getPublicUrl(path).data.publicUrl;
}
function labelGrao(grao) {
  return grao === "profesional" ? "Grao Profesional" : "Grao Elemental";
}
const TIPOS_MOVEMENTO = ["Concertos", "Sonatas", "Pezas"];
function tituloConNumero(titulo, numeroEstudo, tipo) {
  if (!numeroEstudo) return titulo;
  if (tipo && TIPOS_MOVEMENTO.includes(tipo)) return `${titulo} — ${numeroEstudo}º movemento`;
  return `${titulo} Nº${numeroEstudo}`;
}

function CampoAutor({ valor, onChange, autoresSuxeridos, placeholder }) {
  const [aberto, setAberto] = useState(false);
  const contenedorRef = useRef(null);

  useEffect(() => {
    function onFora(e) {
      if (contenedorRef.current && !contenedorRef.current.contains(e.target)) setAberto(false);
    }
    document.addEventListener("mousedown", onFora);
    document.addEventListener("touchstart", onFora);
    return () => {
      document.removeEventListener("mousedown", onFora);
      document.removeEventListener("touchstart", onFora);
    };
  }, []);

  const q = (valor || "").trim().toLowerCase();
  const suxestions = (autoresSuxeridos || [])
    .filter(a => !q || (a.toLowerCase().includes(q) && a.toLowerCase() !== q))
    .slice(0, 8);

  return (
    <div ref={contenedorRef} style={{ position: "relative" }}>
      <input type="text" value={valor || ""} placeholder={placeholder}
        onChange={e => { onChange(e.target.value); setAberto(true); }}
        onFocus={() => setAberto(true)} autoComplete="off" />
      {aberto && suxestions.length > 0 && (
        <div className="autocompletar">
          {suxestions.map(a => (
            <div key={a} className="autocompletar-opcion"
              onMouseDown={e => { e.preventDefault(); onChange(a); setAberto(false); }}>
              {a}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function TagInput({ valores, onChange, placeholder }) {
  const [texto, setTexto] = useState("");
  function engadir() {
    const v = texto.trim();
    if (!v) return;
    if (!valores.includes(v)) onChange([...valores, v]);
    setTexto("");
  }
  function quitar(v) { onChange(valores.filter(x => x !== v)); }
  return (
    <div>
      <div style={{ marginBottom: 6 }}>
        {valores.map(v => (
          <span key={v} className="chip">{v}<button type="button" onClick={()=>quitar(v)}>✕</button></span>
        ))}
      </div>
      <div style={{ display: "flex", gap: 6 }}>
        <input type="text" placeholder={placeholder || "Engadir…"} value={texto}
          onChange={e=>setTexto(e.target.value)}
          onKeyDown={e=>{ if (e.key === "Enter") { e.preventDefault(); engadir(); } }} />
        <button type="button" className="btn" onClick={engadir}>+</button>
      </div>
    </div>
  );
}

function FormObraXeral({ obra, autoresSuxeridos, onClose, onGardado }) {
  const [modo, setModo] = useState("rapido");
  const [f, setF] = useState({
    tipo: obra?.tipo || "Estudos", titulo: obra?.titulo || "", autor: obra?.autor || "",
    niveis: obra?.niveis || [], observacions: obra?.observacions || "",
    total_estudos: (obra?.total_estudos ?? "") === null ? "" : (obra?.total_estudos ?? ""),
  });
  const [ficheiro, setFicheiro] = useState(null);
  const [ficheiroPiano, setFicheiroPiano] = useState(null);
  const [subindo, setSubindo] = useState(false);

  const [tipoRapido, setTipoRapido] = useState(obra?.tipo || "Estudos");
  const [tituloRapido, setTituloRapido] = useState("");
  const [autorRapido, setAutorRapido] = useState("");
  const [esColeccion, setEsColeccion] = useState(false);
  const [totalRapido, setTotalRapido] = useState("");
  const [engadindo, setEngadindo] = useState(false);
  const tituloRef = useRef(null);

  async function gardar(e) {
    e.preventDefault();
    setSubindo(true);
    let pdf_path = obra?.pdf_path || null;
    let pdf_nome = obra?.pdf_nome || null;
    if (ficheiro) {
      const path = `obras/${obra?.id || generarUUID()}.pdf`;
      const { error: eUp } = await sb.storage.from("repertorio").upload(path, ficheiro, { upsert: true, contentType: "application/pdf" });
      if (eUp) { aviso("Erro ao subir o PDF: " + eUp.message, "erro"); setSubindo(false); return; }
      pdf_path = path; pdf_nome = ficheiro.name;
    }
    let pdf_piano_path = obra?.pdf_piano_path || null;
    let pdf_piano_nome = obra?.pdf_piano_nome || null;
    if (ficheiroPiano) {
      const pathPiano = `obras/${obra?.id || generarUUID()}-piano.pdf`;
      const { error: eUpP } = await sb.storage.from("repertorio").upload(pathPiano, ficheiroPiano, { upsert: true, contentType: "application/pdf" });
      if (eUpP) { aviso("Erro ao subir o PDF de piano: " + eUpP.message, "erro"); setSubindo(false); return; }
      pdf_piano_path = pathPiano; pdf_piano_nome = ficheiroPiano.name;
    }
    const payload = {
      tipo: f.tipo, titulo: f.titulo, autor: f.autor, niveis: f.niveis, observacions: f.observacions, pdf_path, pdf_nome,
      pdf_piano_path, pdf_piano_nome,
      total_estudos: f.total_estudos === "" ? null : Number(f.total_estudos),
    };
    let error;
    if (obra?.id) {
      ({ error } = await sb.from("repertorio_xeral").update(payload).eq("id", obra.id));
    } else {
      const { data: max } = await sb.from("repertorio_xeral").select("orde").eq("tipo", f.tipo).order("orde", { ascending: false }).limit(1);
      const orde = (max && max[0] ? max[0].orde : 0) + 1;
      ({ error } = await sb.from("repertorio_xeral").insert({ ...payload, orde }));
    }
    setSubindo(false);
    if (error) { aviso(error.message, "erro"); return; }
    onGardado();
  }

  async function engadirRapido(e) {
    e.preventDefault();
    if (!tituloRapido.trim()) return;
    if (esColeccion && !totalRapido.trim()) return;
    setEngadindo(true);
    const { data: max } = await sb.from("repertorio_xeral").select("orde").eq("tipo", tipoRapido).order("orde", { ascending: false }).limit(1);
    const orde = (max && max[0] ? max[0].orde : 0) + 1;
    const { error } = await sb.from("repertorio_xeral").insert({
      tipo: tipoRapido, titulo: tituloRapido.trim(), autor: autorRapido.trim() || null,
      total_estudos: esColeccion ? Number(totalRapido) : null, orde,
    });
    setEngadindo(false);
    if (error) { aviso(error.message, "erro"); return; }
    setTituloRapido(""); setAutorRapido(""); setTotalRapido(""); setEsColeccion(false);
    if (tituloRef.current) tituloRef.current.focus();
    onGardado(false);
  }

  if (!obra && modo === "rapido") {
    return (
      <Modal title="Nova obra" onClose={onClose}>
        <form onSubmit={engadirRapido}>
          <label>Tipo</label>
          <select className="field" value={tipoRapido} onChange={e=>setTipoRapido(e.target.value)}>
            {TIPOS_REPERTORIO.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <label>Título</label>
          <input ref={tituloRef} type="text" value={tituloRapido} onChange={e=>setTituloRapido(e.target.value)} required />
          <label>Autor (opcional)</label>
          <CampoAutor valor={autorRapido} onChange={setAutorRapido} autoresSuxeridos={autoresSuxeridos} />
          <label style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 14 }}>
            <input type="checkbox" checked={esColeccion} onChange={e=>setEsColeccion(e.target.checked)} style={{ width: 18, height: 18 }} />
            {TIPOS_MOVEMENTO.includes(tipoRapido) ? "Ten varios movementos" : "É unha colección numerada (ex. 42 estudos)"}
          </label>
          {esColeccion && (
            <div style={{ marginTop: 8 }}>
              <label>{TIPOS_MOVEMENTO.includes(tipoRapido) ? "Cantos movementos ten" : "Cantos números ten"}</label>
              <input type="text" inputMode="numeric" value={totalRapido} onChange={e=>setTotalRapido(e.target.value)} required={esColeccion} />
              <div className="field-note">
                {TIPOS_MOVEMENTO.includes(tipoRapido)
                  ? "Despois, ao asignarllo a un alumno, eliges que movemento(s) concreto(s) traballa."
                  : "Despois, ao asignarllo a un alumno, eliges que número concreto traballa."}
              </div>
            </div>
          )}
          <div className="row-actions">
            <button type="button" className="btn" onClick={onClose}>Rematar</button>
            <button type="button" className="btn btn-ghost" onClick={()=>setModo("normal")}>Formulario completo</button>
            <button className="btn btn-primary" disabled={engadindo}>{engadindo ? "Engadindo…" : "+ Engadir"}</button>
          </div>
        </form>
      </Modal>
    );
  }

  return (
    <Modal title={obra ? "Editar obra" : "Nova obra"} onClose={onClose}>
      {!obra && (
        <button type="button" className="btn btn-ghost" style={{ padding: "2px 0", marginBottom: 8, fontSize: 12.5 }} onClick={()=>setModo("rapido")}>
          ← Usar engadido rápido (autor + número)
        </button>
      )}
      <form onSubmit={gardar}>
        <label>Tipo</label>
        <select className="field" value={f.tipo} onChange={e=>setF({...f,tipo:e.target.value})}>
          {TIPOS_REPERTORIO.map(t => <option key={t} value={t}>{t}</option>)}
        </select>
        <Campo label="Título" value={f.titulo} onChange={e=>setF({...f,titulo:e.target.value})} required />
        <label>Autor</label>
        <CampoAutor valor={f.autor} onChange={v=>setF({...f,autor:v})} autoresSuxeridos={autoresSuxeridos} />
        <Campo label="Total de estudos/movementos (se é un libro, colección ou obra con varios movementos)" type="text" inputMode="numeric" value={f.total_estudos} onChange={e=>setF({...f,total_estudos:e.target.value})} />
        <label>Niveis</label>
        <TagInput valores={f.niveis} onChange={v=>setF({...f,niveis:v})} placeholder="p.ex. 2º GE" />
        <label>Observacións</label>
        <textarea value={f.observacions} onChange={e=>setF({...f,observacions:e.target.value})}></textarea>
        <label>PDF — parte principal{obra?.pdf_nome ? ` (actual: ${obra.pdf_nome})` : ""}</label>
        <input type="file" accept="application/pdf" onChange={e=>setFicheiro(e.target.files[0])} />
        <div className="field-note">{obra?.pdf_path ? "Sube un arquivo novo para substituír o PDF actual." : "Opcional."}</div>
        <label>PDF — acompañamento de piano{obra?.pdf_piano_nome ? ` (actual: ${obra.pdf_piano_nome})` : ""}</label>
        <input type="file" accept="application/pdf" onChange={e=>setFicheiroPiano(e.target.files[0])} />
        <div className="field-note">{obra?.pdf_piano_path ? "Sube un arquivo novo para substituír o PDF actual." : "Opcional. Aparecerá en Pianistas."}</div>
        <div className="row-actions">
          <button type="button" className="btn" onClick={onClose}>Cancelar</button>
          <button className="btn btn-primary" disabled={subindo}>{subindo ? "Gardando…" : "Gardar"}</button>
        </div>
      </form>
    </Modal>
  );
}

function exportarPianistaPDF(nomePianista, trimestreLabel, listaAlumnos) {
  const doc = new window.jspdf.jsPDF();
  cabeceiraPDF(doc, `Repertorio para ${nomePianista}`);
  let y = 48;
  doc.setFontSize(10); doc.setTextColor(90, 114, 144);
  doc.text(`${trimestreLabel}`, 14, y); y += 9;

  listaAlumnos.forEach((a,i) => {
    y = asegurarEspazo(doc, y, 16);
    if (i > 0) { doc.setDrawColor(227,233,242); doc.line(14, y, 196, y); y += 8; }
    doc.setFontSize(11.5); doc.setFont(undefined, "bold"); doc.setTextColor(13, 79, 139);
    doc.text(`${a.alumno.nome} ${a.alumno.apelidos||""}`, 14, y); y += 6;
    doc.setFontSize(9); doc.setFont(undefined, "normal"); doc.setTextColor(90, 114, 144);
    doc.text(`${a.curso || "-"} · ${labelGrao(a.grao)}`, 14, y); y += 7;
    doc.setFontSize(10); doc.setTextColor(10, 37, 64);
    a.obras.forEach(o => {
      const lineas = doc.splitTextToSize(`• ${o.titulo}${o.autor ? " — " + o.autor : ""}`, 178);
      y = asegurarEspazo(doc, y, lineas.length*5.5);
      doc.text(lineas, 16, y); y += lineas.length*5.5;
    });
    y += 2;
  });

  const nomeArquivo = `Repertorio_${nomePianista.replace(/\s+/g,"_")}.pdf`;
  doc.save(nomeArquivo);
  return nomeArquivo;
}

function PianistasXeral({ anoEscolar }) {
  const [trimestre, setTrimestre] = useState(1);
  const [datos, setDatos] = useState(null);
  const [pianistaActivo, setPianistaActivo] = useState(null);
  const [xerandoPdf, setXerandoPdf] = useState(false);

  async function cargar() {
    setDatos(null);
    const { data: matriculas, error } = await sb
      .from("matriculas")
      .select("id, curso, grao, alumnos(nome,apelidos,activo,email_alumno,email_pai,email_nai), materias(nome, pianista_acompanante)")
      .eq("curso_escolar", anoEscolar);
    if (error) { aviso(error.message, "erro"); return; }
    if (!matriculas.length) { setDatos({}); return; }

    const infoMatricula = {};
    matriculas.forEach(m => {
      if (!m.alumnos || m.alumnos.activo === false) return;
      const materiaViolin = (m.materias||[]).find(x=>(x.nome||"").toLowerCase().includes("violín")) || (m.materias||[])[0] || null;
      infoMatricula[m.id] = { alumno: m.alumnos, curso: m.curso, grao: m.grao, pianista: materiaViolin?.pianista_acompanante || "" };
    });

    const { data: obras, error: e2 } = await sb.from("repertorio_asignado")
      .select("*, repertorio_xeral(titulo,autor,pdf_piano_path,pdf_piano_nome)")
      .in("matricula_id", matriculas.map(m=>m.id))
      .eq("trimestre", trimestre)
      .eq("necesita_acompanamento", true);
    if (e2) { aviso(e2.message, "erro"); return; }

    const agrupado = {};
    obras.forEach(o => {
      const info = infoMatricula[o.matricula_id];
      if (!info) return;
      const nomePianista = info.pianista.trim() || "Sen pianista asignado";
      agrupado[nomePianista] = agrupado[nomePianista] || {};
      const chave = o.matricula_id;
      agrupado[nomePianista][chave] = agrupado[nomePianista][chave] || { alumno: info.alumno, curso: info.curso, grao: info.grao, obras: [] };
      agrupado[nomePianista][chave].obras.push({
        id: o.id, entregada: o.entregada, para_ensaiar: o.para_ensaiar, avisado: o.avisado,
        titulo: tituloConNumero(o.repertorio_xeral?.titulo || o.texto_libre || "?", o.numero_estudo, o.tipo),
        autor: o.repertorio_xeral?.autor || null,
        pdfPiano: o.repertorio_xeral?.pdf_piano_path || null,
      });
    });
    setDatos(agrupado);
    setPianistaActivo(prev => {
      const nomes = Object.keys(agrupado);
      return nomes.includes(prev) ? prev : (nomes[0] || null);
    });
  }
  useEffect(() => { cargar(); }, [anoEscolar, trimestre]);

  async function alternarEntregada(obra) {
    await gardarSeguro(sb.from("repertorio_asignado").update({ entregada: !obra.entregada }).eq("id", obra.id), "repertorio_asignado");
    cargar();
  }
  async function alternarParaEnsaiar(obra) {
    const novo = !obra.para_ensaiar;
    await gardarSeguro(sb.from("repertorio_asignado").update({ para_ensaiar: novo, avisado: novo ? false : obra.avisado }).eq("id", obra.id), "repertorio_asignado");
    cargar();
  }
  function avisarAlumno(alumno, obras) {
    const pendentes = obras.filter(o => o.para_ensaiar && !o.avisado);
    if (!pendentes.length) { aviso("Non hai obras novas para avisar a este alumno.", "erro"); return; }
    const corpo = pendentes.map(o => `- ${o.titulo}`).join("\n");
    const destinatarios = [alumno.email_pai, alumno.email_nai, alumno.email_alumno].filter(Boolean).join(",");
    const asunto = encodeURIComponent(`Para ensaiar — ${alumno.nome} ${alumno.apelidos||""}`);
    const corpoCompleto = encodeURIComponent(`Boa tarde,\n\nPara a próxima sesión, ${alumno.nome} ten que ensaiar:\n\n${corpo}\n\nSaúdos,\nJorge Montes`);
    window.location.href = `mailto:${destinatarios}?subject=${asunto}&body=${corpoCompleto}`;
    Promise.all(pendentes.map(o => sb.from("repertorio_asignado").update({ avisado: true }).eq("id", o.id))).then(cargar);
  }

  if (datos === null) return <div className="wrap"><div className="empty">Cargando…</div></div>;
  const nomesPianistas = Object.keys(datos).sort((a,b)=> a==="Sen pianista asignado" ? 1 : b==="Sen pianista asignado" ? -1 : a.localeCompare(b));
  const listaActiva = pianistaActivo ? Object.values(datos[pianistaActivo]||{}) : [];

  function xerarPdf() {
    setXerandoPdf(true);
    const trimestreLabel = TRIMESTRES_REPERTORIO.find(t=>t.n===trimestre).label;
    exportarPianistaPDF(pianistaActivo, trimestreLabel, listaActiva.map(a => ({
      alumno: a.alumno, curso: a.curso, grao: a.grao,
      obras: a.obras.map(o=>({ titulo: o.titulo, autor: o.autor })),
    })));
    setXerandoPdf(false);
  }

  return (
    <div className="wrap">
      <h2 className="serif" style={{ marginBottom: 14, fontSize: 21 }}>Pianistas</h2>
      <div className="tabs" style={{ position: "static", background: "transparent", borderBottom: "none", padding: 0, marginBottom: 10 }}>
        {TRIMESTRES_REPERTORIO.filter(t=>t.n!==4).map(t => (
          <button key={t.n} className={trimestre===t.n?"active":""} onClick={()=>setTrimestre(t.n)}>{t.label}</button>
        ))}
      </div>

      {nomesPianistas.length === 0 && <div className="empty">Non hai obras marcadas "Necesita acompañamento" neste trimestre.</div>}
      {nomesPianistas.length > 0 && (
        <React.Fragment>
          <div className="tabs" style={{ position: "static", background: "transparent", borderBottom: "1px solid var(--crema)", padding: 0, marginBottom: 14 }}>
            {nomesPianistas.map(n => (
              <button key={n} className={pianistaActivo===n?"active":""} onClick={()=>setPianistaActivo(n)}>{n}</button>
            ))}
          </div>
          {pianistaActivo === "Sen pianista asignado" && (
            <div className="field-note" style={{ marginBottom: 10, color: "var(--rojo)" }}>
              Estes alumnos teñen obras marcadas pero non teñen pianista gardado en Materias.
            </div>
          )}
          {listaActiva.map((a,i) => (
            <div key={i} className="card">
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <strong>{a.alumno.nome} {a.alumno.apelidos}</strong>
                <button className="btn btn-ghost" style={{ fontSize: 11.5, padding: "4px 8px" }} onClick={()=>avisarAlumno(a.alumno, a.obras)}>
                  ✉️ Avisar alumno
                </button>
              </div>
              {a.obras.map(o => (
                <div key={o.id} style={{ padding: "6px 0", borderBottom: "1px solid var(--crema)" }}>
                  <div style={{ fontSize: 13.5, marginBottom: 4, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                    <span>{o.titulo}{o.autor ? ` — ${o.autor}` : ""}</span>
                    {o.pdfPiano && (
                      <a className="pdf-link" href={urlPdfRepertorio(o.pdfPiano)} target="_blank" rel="noopener noreferrer">🎹 Ver parte de piano</a>
                    )}
                  </div>
                  <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
                    <label style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12, color: "var(--sepia)" }}>
                      <input type="checkbox" checked={o.entregada} onChange={()=>alternarEntregada(o)} style={{ width: 16, height: 16 }} />
                      Entregada
                    </label>
                    <label style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12, color: "var(--sepia)" }}>
                      <input type="checkbox" checked={o.para_ensaiar} onChange={()=>alternarParaEnsaiar(o)} style={{ width: 16, height: 16 }} />
                      Para ensaiar {o.para_ensaiar && o.avisado && <span style={{ color: "var(--verde)" }}>(avisado)</span>}
                    </label>
                  </div>
                </div>
              ))}
            </div>
          ))}
          <button className="btn btn-block" disabled={xerandoPdf} onClick={xerarPdf}>
            {xerandoPdf ? "Xerando…" : `📄 PDF para ${pianistaActivo}`}
          </button>
        </React.Fragment>
      )}
    </div>
  );
}

function FormEventoAudicion({ anoEscolar, onClose, onCreado }) {
  const [nome, setNome] = useState("");
  const [data, setData] = useState(new Date().toISOString().slice(0,10));
  const [trimestre, setTrimestre] = useState(1);
  const [creando, setCreando] = useState(false);

  async function crear(e) {
    e.preventDefault();
    setCreando(true);
    const { data: evento, error: e1 } = await sb.from("eventos_audicion").insert({
      nome: nome.trim() || "Audición", data, trimestre, curso_escolar: anoEscolar,
    }).select().single();
    if (e1) { aviso(e1.message, "erro"); setCreando(false); return; }

    const { data: matriculas, error: e2 } = await sb.from("matriculas").select("id").eq("curso_escolar", anoEscolar);
    if (e2) { aviso(e2.message, "erro"); setCreando(false); return; }
    const idsMatricula = matriculas.map(m=>m.id);

    if (idsMatricula.length) {
      const { data: obrasMarcadas, error: e3 } = await sb.from("repertorio_asignado")
        .select("id, matricula_id").in("matricula_id", idsMatricula).eq("trimestre", trimestre).eq("audicion", true);
      if (e3) { aviso(e3.message, "erro"); setCreando(false); return; }

      const porMatricula = {};
      obrasMarcadas.forEach(o => { (porMatricula[o.matricula_id] = porMatricula[o.matricula_id] || []).push(o.id); });

      for (const matriculaId of Object.keys(porMatricula)) {
        const { data: audicion, error: e4 } = await sb.from("audicions").insert({
          matricula_id: matriculaId, trimestre, data, evento_audicion_id: evento.id,
        }).select().single();
        if (e4) { aviso(e4.message, "erro"); continue; }
        await gardarSeguro(sb.from("audicions_repertorio").insert(
          porMatricula[matriculaId].map(repId => ({ audicion_id: audicion.id, repertorio_asignado_id: repId }))
        ), "repertorio da audición");
      }
    }
    setCreando(false);
    onCreado();
  }

  return (
    <Modal title="Nova audición" onClose={onClose}>
      <form onSubmit={crear}>
        <Campo label="Nome" value={nome} onChange={e=>setNome(e.target.value)} placeholder="p.ex. Audición de Nadal" required />
        <Campo label="Data" type="date" value={data} onChange={e=>setData(e.target.value)} required />
        <label>Trimestre</label>
        <select className="field" value={trimestre} onChange={e=>setTrimestre(Number(e.target.value))}>
          <option value={1}>1º Trimestre</option>
          <option value={2}>2º Trimestre</option>
          <option value={3}>3º Trimestre</option>
        </select>
        <div className="field-note">Colle automaticamente os alumnos e obras marcadas "Audición" nese trimestre. Despois podes editar cada unha desde a ficha do alumno.</div>
        <div className="row-actions">
          <button type="button" className="btn" onClick={onClose}>Cancelar</button>
          <button className="btn btn-primary" disabled={creando}>{creando ? "Creando…" : "Crear audición"}</button>
        </div>
      </form>
    </Modal>
  );
}

function DetalleEventoAudicion({ evento, onClose, onCambio }) {
  const [filas, setFilas] = useState(null);

  async function cargar() {
    const { data: audicions, error } = await sb.from("audicions")
      .select("id, matricula_id, matriculas(alumnos(nome,apelidos), materias(nome,horarios_materia(dia_semana,hora))), audicions_repertorio(id, repertorio_asignado(texto_libre, numero_estudo, tipo, repertorio_xeral(titulo)))")
      .eq("evento_audicion_id", evento.id);
    if (error) { aviso(error.message, "erro"); return; }

    const procesadas = await Promise.all((audicions||[]).map(async a => {
      const materiaViolin = (a.matriculas?.materias||[]).find(x=>(x.nome||"").toLowerCase().includes("violín")) || (a.matriculas?.materias||[])[0] || null;
      const horario = materiaViolin ? materiaViolin.horarios_materia : [];
      const { data: ultimaClase } = await sb.from("clases").select("data")
        .eq("matricula_id", a.matricula_id).eq("trimestre", evento.trimestre).eq("falta", false)
        .order("data", { ascending: false }).limit(1).maybeSingle();
      const sesions = contarSesionsRestantes(horario, ultimaClase?.data || null, evento.data);
      return {
        id: a.id, alumno: a.matriculas?.alumnos, sesions,
        obras: (a.audicions_repertorio||[]).map(ar => ({
          id: ar.id,
          titulo: tituloConNumero(ar.repertorio_asignado?.repertorio_xeral?.titulo || ar.repertorio_asignado?.texto_libre || "?", ar.repertorio_asignado?.numero_estudo, ar.repertorio_asignado?.tipo),
        })),
      };
    }));
    setFilas(procesadas);
  }
  useEffect(() => { cargar(); }, [evento.id]);

  async function quitarObra(idLigazon) {
    await gardarSeguro(sb.from("audicions_repertorio").delete().eq("id", idLigazon), "audicions_repertorio");
    cargar();
  }
  async function quitarAlumno(audicionId) {
    if (!confirm("Quitar este alumno da audición? (Non se borran as notas que xa tivese esa audición individual)")) return;
    await gardarSeguro(sb.from("audicions").update({ evento_audicion_id: null }).eq("id", audicionId), "audicions");
    cargar();
  }
  async function borrarEvento() {
    if (!confirm(`Eliminar a audición "${evento.nome}"? As audicións individuais xa creadas quedan, pero desligadas deste evento.`)) return;
    await gardarSeguro(sb.from("eventos_audicion").delete().eq("id", evento.id), "eventos_audicion");
    onCambio();
    onClose();
  }

  return (
    <Modal title={evento.nome} onClose={onClose}>
      <div className="field-note" style={{ marginBottom: 10 }}>{formatarDataCurta(evento.data)} · {evento.trimestre}º trimestre</div>
      {filas === null && <div className="empty">Cargando…</div>}
      {filas !== null && filas.length === 0 && <div className="empty">Non hai alumnos con obras marcadas "Audición" nese trimestre.</div>}
      {filas !== null && filas.map(f => (
        <div key={f.id} className="card" style={{ padding: "10px 12px" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <strong>{f.alumno?.nome} {f.alumno?.apelidos}</strong>
            <button className="btn btn-ghost" style={{ fontSize: 11, padding: "3px 8px" }} onClick={()=>quitarAlumno(f.id)}>Quitar</button>
          </div>
          {f.sesions !== null && (
            <div className="field-note" style={{ margin: "3px 0 6px" }}>Quedan {f.sesions} sesión{f.sesions===1?"":"s"} antes da audición</div>
          )}
          {f.obras.map(o => (
            <div key={o.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 13.5, padding: "3px 0" }}>
              <span>{o.titulo}</span>
              <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px" }} onClick={()=>quitarObra(o.id)}>✕</button>
            </div>
          ))}
        </div>
      ))}
      <div className="row-actions">
        <button className="btn" onClick={onClose}>Pechar</button>
        <button className="btn btn-danger" onClick={borrarEvento}>Eliminar audición</button>
      </div>
    </Modal>
  );
}

function TarefasXerais() {
  const [tarefas, setTarefas] = useState(null);
  const [novoTexto, setNovoTexto] = useState("");
  const [mostrarFeitas, setMostrarFeitas] = useState(false);
  const [engadindo, setEngadindo] = useState(false);

  async function cargar() {
    const { data, error } = await sb.from("tarefas_persoais").select("*").order("created_at", { ascending: false });
    if (error) { aviso(error.message, "erro"); return; }
    setTarefas(data);
  }
  useEffect(() => { cargar(); }, []);

  async function engadir(e) {
    e.preventDefault();
    if (!novoTexto.trim()) return;
    setEngadindo(true);
    const { error } = await sb.from("tarefas_persoais").insert({ texto: novoTexto.trim() });
    setEngadindo(false);
    if (error) { aviso(error.message, "erro"); return; }
    setNovoTexto("");
    cargar();
  }
  async function alternarFeita(t) {
    await gardarSeguro(sb.from("tarefas_persoais").update({ feita: !t.feita }).eq("id", t.id), "tarefas_persoais");
    cargar();
  }
  async function borrar(t) {
    await gardarSeguro(sb.from("tarefas_persoais").delete().eq("id", t.id), "tarefas_persoais");
    cargar();
  }

  if (tarefas === null) return <div className="wrap"><div className="empty">Cargando…</div></div>;
  const pendentes = tarefas.filter(t => !t.feita);
  const feitas = tarefas.filter(t => t.feita);

  return (
    <div className="wrap">
      <h2 className="serif" style={{ marginBottom: 14, fontSize: 21 }}>Tarefas</h2>
      <form onSubmit={engadir} className="card">
        <label>Nova tarefa</label>
        <div style={{ display: "flex", gap: 8 }}>
          <input type="text" value={novoTexto} onChange={e=>setNovoTexto(e.target.value)} style={{ flex: 1 }} />
          <button className="btn btn-primary" disabled={engadindo}>{engadindo ? "…" : "+ Engadir"}</button>
        </div>
      </form>

      {pendentes.length === 0 && <div className="empty">Sen tarefas pendentes.</div>}
      {pendentes.map(t => (
        <div key={t.id} className="alumno-row" style={{ cursor: "default" }}>
          <input type="checkbox" checked={false} onChange={()=>alternarFeita(t)} style={{ width: 20, height: 20, flexShrink: 0 }} />
          <div className="info"><div className="nome" style={{ fontWeight: 500 }}>{t.texto}</div></div>
          <button className="btn btn-ghost" style={{ fontSize: 12, padding: "4px 8px" }} onClick={()=>borrar(t)}>✕</button>
        </div>
      ))}

      {feitas.length > 0 && (
        <React.Fragment>
          <button className="btn btn-ghost" style={{ marginTop: 10, fontSize: 12.5 }} onClick={()=>setMostrarFeitas(m=>!m)}>
            {mostrarFeitas ? "Ocultar" : "Mostrar"} feitas ({feitas.length})
          </button>
          {mostrarFeitas && feitas.map(t => (
            <div key={t.id} className="alumno-row" style={{ cursor: "default", opacity: .6 }}>
              <input type="checkbox" checked={true} onChange={()=>alternarFeita(t)} style={{ width: 20, height: 20, flexShrink: 0 }} />
              <div className="info"><div className="nome" style={{ fontWeight: 500, textDecoration: "line-through" }}>{t.texto}</div></div>
              <button className="btn btn-ghost" style={{ fontSize: 12, padding: "4px 8px" }} onClick={()=>borrar(t)}>✕</button>
            </div>
          ))}
        </React.Fragment>
      )}
    </div>
  );
}

function AudicionsXerais({ anoEscolar }) {
  const [eventos, setEventos] = useState(null);
  const [mostrarForm, setMostrarForm] = useState(false);
  const [eventoAberto, setEventoAberto] = useState(null);

  async function cargar() {
    const { data, error } = await sb.from("eventos_audicion").select("*").eq("curso_escolar", anoEscolar).order("data", { ascending: false });
    if (error) { aviso(error.message, "erro"); return; }
    setEventos(data);
  }
  useEffect(() => { cargar(); }, [anoEscolar]);

  if (eventos === null) return <div className="wrap"><div className="empty">Cargando…</div></div>;

  return (
    <div className="wrap">
      <h2 className="serif" style={{ marginBottom: 14, fontSize: 21 }}>Audicións</h2>
      {eventos.length === 0 && <div className="empty">Aínda non hai audicións creadas.<br/>Toca "+" para crear a primeira.</div>}
      {eventos.map(ev => (
        <div key={ev.id} className="alumno-row" onClick={()=>setEventoAberto(ev)}>
          <div className="info">
            <div className="nome">{ev.nome}</div>
            <div className="meta">{formatarDataCurta(ev.data)} · {ev.trimestre}º trimestre</div>
          </div>
        </div>
      ))}
      <button className="fab" onClick={()=>setMostrarForm(true)}>+</button>
      {mostrarForm && <FormEventoAudicion anoEscolar={anoEscolar} onClose={()=>setMostrarForm(false)} onCreado={()=>{ setMostrarForm(false); cargar(); }} />}
      {eventoAberto && <DetalleEventoAudicion evento={eventoAberto} onClose={()=>setEventoAberto(null)} onCambio={cargar} />}
    </div>
  );
}

function FormLibro({ libro, onClose, onGardado }) {
  const [f, setF] = useState({ titulo: libro?.titulo || "", autor: libro?.autor || "", tipo: libro?.tipo || "Pezas" });
  const [ficheiro, setFicheiro] = useState(null);
  const [gardando, setGardando] = useState(false);

  async function gardar(e) {
    e.preventDefault();
    setGardando(true);
    let pdf_path = libro?.pdf_path || null;
    let pdf_nome = libro?.pdf_nome || null;
    if (ficheiro) {
      const path = `obras/${libro?.id || generarUUID()}-libro.pdf`;
      const { error: eUp } = await sb.storage.from("repertorio").upload(path, ficheiro, { upsert: true, contentType: "application/pdf" });
      if (eUp) { aviso("Erro ao subir o PDF: " + eUp.message, "erro"); setGardando(false); return; }
      pdf_path = path; pdf_nome = ficheiro.name;
    }
    const payload = { titulo: f.titulo, autor: f.autor, tipo: f.tipo, es_libro: true, pdf_path, pdf_nome };
    let error;
    if (libro?.id) {
      ({ error } = await sb.from("repertorio_xeral").update(payload).eq("id", libro.id));
    } else {
      ({ error } = await sb.from("repertorio_xeral").insert(payload));
    }
    setGardando(false);
    if (error) { aviso(error.message, "erro"); return; }
    onGardado();
  }

  return (
    <Modal title={libro ? "Editar libro" : "Novo libro"} onClose={onClose}>
      <form onSubmit={gardar}>
        <Campo label="Título do libro" value={f.titulo} onChange={e=>setF({...f,titulo:e.target.value})} required />
        <Campo label="Autor / Compilador" value={f.autor} onChange={e=>setF({...f,autor:e.target.value})} />
        <label>Tipo das pezas que contén</label>
        <select className="field" value={f.tipo} onChange={e=>setF({...f,tipo:e.target.value})}>
          {TIPOS_REPERTORIO.map(t => <option key={t} value={t}>{t}</option>)}
        </select>
        <label>PDF do libro completo{libro?.pdf_nome ? ` (actual: ${libro.pdf_nome})` : ""}</label>
        <input type="file" accept="application/pdf" onChange={e=>setFicheiro(e.target.files[0])} />
        <div className="field-note">Opcional — o libro enteiro escaneado, se o tes.</div>
        <div className="row-actions">
          <button type="button" className="btn" onClick={onClose}>Cancelar</button>
          <button className="btn btn-primary" disabled={gardando}>{gardando ? "Gardando…" : "Gardar"}</button>
        </div>
      </form>
    </Modal>
  );
}

function FormPeza({ libro, peza, autoresSuxeridos, onClose, onGardado }) {
  const [f, setF] = useState({ titulo: peza?.titulo || "", autor: peza?.autor || "" });
  const [ficheiro, setFicheiro] = useState(null);
  const [ficheiroPiano, setFicheiroPiano] = useState(null);
  const [gardando, setGardando] = useState(false);

  async function gardar(e) {
    e.preventDefault();
    setGardando(true);
    let pdf_path = peza?.pdf_path || null;
    let pdf_nome = peza?.pdf_nome || null;
    if (ficheiro) {
      const path = `obras/${peza?.id || generarUUID()}.pdf`;
      const { error: eUp } = await sb.storage.from("repertorio").upload(path, ficheiro, { upsert: true, contentType: "application/pdf" });
      if (eUp) { aviso("Erro ao subir o PDF: " + eUp.message, "erro"); setGardando(false); return; }
      pdf_path = path; pdf_nome = ficheiro.name;
    }
    let pdf_piano_path = peza?.pdf_piano_path || null;
    let pdf_piano_nome = peza?.pdf_piano_nome || null;
    if (ficheiroPiano) {
      const pathP = `obras/${peza?.id || generarUUID()}-piano.pdf`;
      const { error: eUpP } = await sb.storage.from("repertorio").upload(pathP, ficheiroPiano, { upsert: true, contentType: "application/pdf" });
      if (eUpP) { aviso("Erro ao subir o PDF de piano: " + eUpP.message, "erro"); setGardando(false); return; }
      pdf_piano_path = pathP; pdf_piano_nome = ficheiroPiano.name;
    }
    const payload = {
      titulo: f.titulo, autor: f.autor, tipo: libro.tipo, libro_id: libro.id,
      pdf_path, pdf_nome, pdf_piano_path, pdf_piano_nome,
    };
    let error;
    if (peza?.id) {
      ({ error } = await sb.from("repertorio_xeral").update(payload).eq("id", peza.id));
    } else {
      const { data: max } = await sb.from("repertorio_xeral").select("orde").eq("libro_id", libro.id).order("orde", { ascending: false }).limit(1);
      const orde = (max && max[0] ? max[0].orde : 0) + 1;
      ({ error } = await sb.from("repertorio_xeral").insert({ ...payload, orde }));
    }
    setGardando(false);
    if (error) { aviso(error.message, "erro"); return; }
    onGardado();
  }

  return (
    <Modal title={peza ? "Editar peza" : "Nova peza"} onClose={onClose}>
      <form onSubmit={gardar}>
        <Campo label="Título da peza" value={f.titulo} onChange={e=>setF({...f,titulo:e.target.value})} required />
        <label>Autor</label>
        <CampoAutor valor={f.autor} onChange={v=>setF({...f,autor:v})} autoresSuxeridos={autoresSuxeridos} />
        <label>PDF — parte principal{peza?.pdf_nome ? ` (actual: ${peza.pdf_nome})` : ""}</label>
        <input type="file" accept="application/pdf" onChange={e=>setFicheiro(e.target.files[0])} />
        <label>PDF — acompañamento de piano{peza?.pdf_piano_nome ? ` (actual: ${peza.pdf_piano_nome})` : ""}</label>
        <input type="file" accept="application/pdf" onChange={e=>setFicheiroPiano(e.target.files[0])} />
        <div className="row-actions">
          <button type="button" className="btn" onClick={onClose}>Cancelar</button>
          <button className="btn btn-primary" disabled={gardando}>{gardando ? "Gardando…" : "Gardar"}</button>
        </div>
      </form>
    </Modal>
  );
}

function DetalleLibro({ libro, autoresSuxeridos, onClose, onCambio }) {
  const [pezas, setPezas] = useState(null);
  const [mostrarFormLibro, setMostrarFormLibro] = useState(false);
  const [mostrarFormPeza, setMostrarFormPeza] = useState(false);
  const [editandoPeza, setEditandoPeza] = useState(null);
  const [libroActual, setLibroActual] = useState(libro);

  async function cargar() {
    const { data, error } = await sb.from("repertorio_xeral").select("*").eq("libro_id", libro.id).order("orde");
    if (error) { aviso(error.message, "erro"); return; }
    setPezas(data);
  }
  useEffect(() => { cargar(); }, [libro.id]);

  async function recargarLibro() {
    const { data } = await sb.from("repertorio_xeral").select("*").eq("id", libro.id).single();
    if (data) setLibroActual(data);
  }

  async function eliminarLibro() {
    if (!confirm(`Eliminar o libro "${libroActual.titulo}" e TODAS as súas ${pezas?.length||0} pezas? Tamén desaparecerán dos alumnos que as teñan asignadas.`)) return;
    if (libroActual.pdf_path) await sb.storage.from("repertorio").remove([libroActual.pdf_path]);
    await gardarSeguro(sb.from("repertorio_xeral").delete().eq("id", libroActual.id), "repertorio_xeral");
    onCambio();
    onClose();
  }
  async function eliminarPeza(peza) {
    if (!confirm(`Eliminar "${peza.titulo}"?`)) return;
    if (peza.pdf_path) await sb.storage.from("repertorio").remove([peza.pdf_path]);
    if (peza.pdf_piano_path) await sb.storage.from("repertorio").remove([peza.pdf_piano_path]);
    await gardarSeguro(sb.from("repertorio_xeral").delete().eq("id", peza.id), "repertorio_xeral");
    cargar();
  }

  return (
    <Modal title={libroActual.titulo} onClose={onClose}>
      <div className="field-note" style={{ marginBottom: 10 }}>
        {libroActual.autor && <span>{libroActual.autor} · </span>}{libroActual.tipo}
      </div>
      <div className="row-actions" style={{ marginBottom: 14 }}>
        <button className="btn btn-ghost" style={{ fontSize: 12 }} onClick={()=>setMostrarFormLibro(true)}>Editar libro</button>
        {libroActual.pdf_path && (
          <a className="pdf-link" href={urlPdfRepertorio(libroActual.pdf_path)} target="_blank" rel="noopener noreferrer">📄 PDF completo</a>
        )}
        <button className="btn btn-danger" style={{ fontSize: 12, marginLeft: "auto" }} onClick={eliminarLibro}>Eliminar libro</button>
      </div>

      {pezas === null && <div className="empty">Cargando…</div>}
      {pezas !== null && pezas.length === 0 && <div className="empty">Aínda non hai pezas neste libro.</div>}
      {pezas !== null && pezas.map(p => (
        <div key={p.id} className="obra-row">
          <div style={{ flex: 1, minWidth: 0 }}>
            <div className="titulo">{p.titulo}</div>
            {p.autor && <div className="autor">{p.autor}</div>}
          </div>
          {p.pdf_path && <a className="pdf-link" href={urlPdfRepertorio(p.pdf_path)} target="_blank" rel="noopener noreferrer">📄</a>}
          {p.pdf_piano_path && <a className="pdf-link" href={urlPdfRepertorio(p.pdf_piano_path)} target="_blank" rel="noopener noreferrer">🎹</a>}
          <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: 12 }} onClick={()=>setEditandoPeza(p)}>Editar</button>
          <button className="btn btn-danger" style={{ padding: "4px 8px", fontSize: 12 }} onClick={()=>eliminarPeza(p)}>✕</button>
        </div>
      ))}

      <button className="btn btn-block" style={{ marginTop: 12 }} onClick={()=>setMostrarFormPeza(true)}>+ Engadir peza</button>
      <div className="row-actions">
        <button className="btn" onClick={onClose}>Pechar</button>
      </div>

      {mostrarFormLibro && (
        <FormLibro libro={libroActual} onClose={()=>setMostrarFormLibro(false)}
          onGardado={()=>{ setMostrarFormLibro(false); recargarLibro(); onCambio(); }} />
      )}
      {mostrarFormPeza && (
        <FormPeza libro={libroActual} autoresSuxeridos={autoresSuxeridos} onClose={()=>setMostrarFormPeza(false)}
          onGardado={()=>{ setMostrarFormPeza(false); cargar(); onCambio(); }} />
      )}
      {editandoPeza && (
        <FormPeza libro={libroActual} peza={editandoPeza} autoresSuxeridos={autoresSuxeridos} onClose={()=>setEditandoPeza(null)}
          onGardado={()=>{ setEditandoPeza(null); cargar(); onCambio(); }} />
      )}
    </Modal>
  );
}

function RepertorioXeral() {
  const [obras, setObras] = useState(null);
  const [filtroTipo, setFiltroTipo] = useState("");
  const [busca, setBusca] = useState("");
  const [mostrarForm, setMostrarForm] = useState(false);
  const [editando, setEditando] = useState(null);
  const [tiposOrdenando, setTiposOrdenando] = useState({});
  const [abertaId, setAbertaId] = useState(null);
  const [vista, setVista] = useState("obras");
  const [mostrarFormLibro, setMostrarFormLibro] = useState(false);
  const [libroAberto, setLibroAberto] = useState(null);
  const [editandoPeza, setEditandoPeza] = useState(null);
  function alternarOrdenar(tipo) { setTiposOrdenando(prev => ({ ...prev, [tipo]: !prev[tipo] })); }

  async function cargar() {
    const { data, error } = await sb.from("repertorio_xeral").select("*").order("tipo").order("orde");
    if (error) { aviso(error.message, "erro"); return; }
    setObras(data);
  }
  useEffect(() => { cargar(); }, []);

  const autoresExistentes = useMemo(() => {
    if (!obras) return [];
    return [...new Set(obras.map(o => o.autor).filter(Boolean))].sort();
  }, [obras]);

  const obrasSoltas = useMemo(() => (obras || []).filter(o => !o.es_libro), [obras]);
  const librosPorIdXeral = useMemo(() => {
    const m = {};
    (obras || []).filter(o => o.es_libro).forEach(l => { m[l.id] = l; });
    return m;
  }, [obras]);
  const libros = useMemo(() => (obras || []).filter(o => o.es_libro), [obras]);

  async function eliminar(obra) {
    if (!confirm(`Eliminar "${obra.titulo}" do repertorio xeral? Tamén desaparecerá dos alumnos que a teñan asignada.`)) return;
    if (obra.pdf_path) await sb.storage.from("repertorio").remove([obra.pdf_path]);
    await gardarSeguro(sb.from("repertorio_xeral").delete().eq("id", obra.id), "repertorio_xeral");
    cargar();
  }

  async function mover(obra, grupo, dir) {
    const i = grupo.findIndex(o => o.id === obra.id);
    const j = i + dir;
    if (j < 0 || j >= grupo.length) return;
    const outro = grupo[j];
    await gardarSeguro(sb.from("repertorio_xeral").update({ orde: outro.orde }).eq("id", obra.id), "repertorio_xeral");
    await gardarSeguro(sb.from("repertorio_xeral").update({ orde: obra.orde }).eq("id", outro.id), "repertorio_xeral");
    cargar();
  }

  const filtradas = useMemo(() => {
    return obrasSoltas.filter(o => {
      if (filtroTipo && o.tipo !== filtroTipo) return false;
      const q = busca.trim().toLowerCase();
      if (!q) return true;
      const nomeLibro = o.libro_id && librosPorIdXeral[o.libro_id] ? librosPorIdXeral[o.libro_id].titulo : "";
      return `${o.titulo} ${o.autor||""} ${(o.niveis||[]).join(" ")} ${nomeLibro}`.toLowerCase().includes(q);
    });
  }, [obrasSoltas, filtroTipo, busca, librosPorIdXeral]);

  const agrupadas = useMemo(() => {
    const g = {};
    TIPOS_REPERTORIO.forEach(t => g[t] = []);
    filtradas.forEach(o => { (g[o.tipo] = g[o.tipo] || []).push(o); });
    return g;
  }, [filtradas]);

  if (obras === null) return <div className="wrap"><div className="empty">Cargando…</div></div>;

  return (
    <div className="wrap">
      <h2 className="serif" style={{ marginBottom: 14, fontSize: 21 }}>Repertorio xeral</h2>
      <div className="subtabs" style={{ marginBottom: 14 }}>
        <button className={vista==="obras"?"active":""} onClick={()=>setVista("obras")}>Todas as obras</button>
        <button className={vista==="libros"?"active":""} onClick={()=>setVista("libros")}>Libros ({libros.length})</button>
      </div>

      {vista === "obras" ? (
        <React.Fragment>
      <div className="toolbar">
        <input className="search" type="text" placeholder="Buscar título, autor ou nivel…" value={busca} onChange={e=>setBusca(e.target.value)} />
        <select className="field" style={{ maxWidth: 170 }} value={filtroTipo} onChange={e=>setFiltroTipo(e.target.value)}>
          <option value="">Todos os tipos</option>
          {TIPOS_REPERTORIO.map(t => <option key={t} value={t}>{t}</option>)}
        </select>
      </div>

      {TIPOS_REPERTORIO.map(tipo => (
        (!filtroTipo || filtroTipo === tipo) && agrupadas[tipo] && agrupadas[tipo].length > 0 && (
          <div className="grupo-tipo card" key={tipo}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <h4 style={{ margin: 0 }}>{tipo}</h4>
              {agrupadas[tipo].length > 1 && (
                <button type="button" className="btn btn-ghost" style={{ fontSize: 11, padding: "3px 8px" }} onClick={()=>alternarOrdenar(tipo)}>
                  {tiposOrdenando[tipo] ? "Feito" : "Ordenar"}
                </button>
              )}
            </div>
            {agrupadas[tipo].map((o,i) => (
              <FilaEliminable key={o.id} id={o.id} abertaId={abertaId} onAbrirSwipe={setAbertaId} onEliminar={()=>eliminar(o)}>
              <div className="obra-row">
                {tiposOrdenando[tipo] && (
                  <div className="reordenar">
                    <button type="button" title="Subir esta obra" onClick={()=>mover(o,agrupadas[tipo],-1)} disabled={i===0}>▲</button>
                    <button type="button" title="Baixar esta obra" onClick={()=>mover(o,agrupadas[tipo],1)} disabled={i===agrupadas[tipo].length-1}>▼</button>
                  </div>
                )}
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div className="titulo">{o.titulo}{o.total_estudos ? (TIPOS_MOVEMENTO.includes(o.tipo) ? ` — ${o.total_estudos} movementos` : ` — ${o.total_estudos} estudos`) : ""}</div>
                  {o.autor && <div className="autor">{o.autor}</div>}
                  {o.libro_id && librosPorIdXeral[o.libro_id] && (
                    <span className="chip" style={{ cursor: "default", background: "#eee8fd", color: "#5b3bc4" }}>📚 {librosPorIdXeral[o.libro_id].titulo}</span>
                  )}
                  {(o.niveis||[]).length > 0 && (
                    <div style={{ marginTop: 4 }}>
                      {o.niveis.map(n => <span key={n} className="chip" style={{ cursor: "default" }}>{n}</span>)}
                    </div>
                  )}
                  {o.observacions && <div style={{ fontSize: 12, color: "var(--sepia)", marginTop: 4 }}>{o.observacions}</div>}
                </div>
                {o.pdf_path && (
                  <a className="pdf-link" href={urlPdfRepertorio(o.pdf_path)} target="_blank" rel="noopener noreferrer">📄 PDF</a>
                )}
                {o.pdf_piano_path && (
                  <a className="pdf-link" href={urlPdfRepertorio(o.pdf_piano_path)} target="_blank" rel="noopener noreferrer">🎹 Piano</a>
                )}
                <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: 12 }}
                  onClick={()=> o.libro_id ? setEditandoPeza({ peza: o, libro: librosPorIdXeral[o.libro_id] }) : setEditando(o)}>Editar</button>
              </div>
              </FilaEliminable>
            ))}
          </div>
        )
      ))}
      {filtradas.length === 0 && <div className="empty">Non hai obras {(busca||filtroTipo) ? "que coincidan coa busca." : "no repertorio xeral aínda."}</div>}

      <button className="fab" onClick={()=>setMostrarForm(true)}>+</button>
      {mostrarForm && (
        <FormObraXeral autoresSuxeridos={autoresExistentes} onClose={()=>setMostrarForm(false)}
          onGardado={(pechar)=>{ if (pechar !== false) setMostrarForm(false); cargar(); }} />
      )}
      {editando && (
        <FormObraXeral obra={editando} autoresSuxeridos={autoresExistentes} onClose={()=>setEditando(null)}
          onGardado={()=>{ setEditando(null); cargar(); }} />
      )}
      {editandoPeza && (
        <FormPeza libro={editandoPeza.libro} peza={editandoPeza.peza} autoresSuxeridos={autoresExistentes}
          onClose={()=>setEditandoPeza(null)} onGardado={()=>{ setEditandoPeza(null); cargar(); }} />
      )}
        </React.Fragment>
      ) : (
        <React.Fragment>
          {libros.length === 0 && <div className="empty">Aínda non hai libros.<br/>Toca "+" para crear o primeiro.</div>}
          {libros.map(l => (
            <div key={l.id} className="alumno-row" onClick={()=>setLibroAberto(l)}>
              <div className="info">
                <div className="nome">{l.titulo}</div>
                <div className="meta">{l.autor ? `${l.autor} · ` : ""}{l.tipo}</div>
              </div>
              <span className="tag">{l.pdf_path ? "📄" : ""}</span>
            </div>
          ))}
          <button className="fab" onClick={()=>setMostrarFormLibro(true)}>+</button>
          {mostrarFormLibro && (
            <FormLibro onClose={()=>setMostrarFormLibro(false)} onGardado={()=>{ setMostrarFormLibro(false); cargar(); }} />
          )}
          {libroAberto && (
            <DetalleLibro libro={libroAberto} autoresSuxeridos={autoresExistentes}
              onClose={()=>setLibroAberto(null)} onCambio={cargar} />
          )}
        </React.Fragment>
      )}
    </div>
  );
}

function HistorialObra({ titulo, matriculaId, repertorioAsignadoId, onClose }) {
  const [sesions, setSesions] = useState(null);
  useEffect(() => {
    (async () => {
      const { data, error } = await sb.from("clases_repertorio")
        .select("progreso, clases(data, trimestre)")
        .eq("repertorio_asignado_id", repertorioAsignadoId)
        .order("data", { foreignTable: "clases", ascending: true });
      if (error) { aviso(error.message, "erro"); return; }
      setSesions((data||[]).filter(s => s.clases));
    })();
  }, [repertorioAsignadoId]);

  return (
    <Modal title={`Historial — ${titulo}`} onClose={onClose}>
      {sesions === null && <div className="empty">Cargando…</div>}
      {sesions !== null && sesions.length === 0 && <div className="empty">Aínda non hai clases rexistradas con esta obra.</div>}
      {sesions !== null && sesions.map((s,i) => (
        <div key={i} className="titoria-item">
          <strong>{formatarDataCurta(s.clases.data)}</strong>
          {s.progreso && <div style={{ fontSize: 13.5, marginTop: 3 }}>{s.progreso}</div>}
        </div>
      ))}
      <div className="row-actions">
        <button className="btn" onClick={onClose}>Pechar</button>
      </div>
    </Modal>
  );
}

function SeccionRepertorioTipo({ matriculaId, trimestre, tipo, catalogo, itens, onCambio }) {
  const [mostrarAdd, setMostrarAdd] = useState(false);
  const [modo, setModo] = useState("catalogo");
  const [seleccionado, setSeleccionado] = useState("");
  const [numerosEstudo, setNumerosEstudo] = useState("");
  const [textoLibre, setTextoLibre] = useState("");
  const [ordenando, setOrdenando] = useState(false);
  const [abertaId, setAbertaId] = useState(null);
  const [historialAberto, setHistorialAberto] = useState(null);
  const opcionsCatalogo = catalogo.filter(o => o.tipo === tipo && !o.es_libro);
  const librosPorId = useMemo(() => {
    const m = {};
    catalogo.filter(o => o.es_libro).forEach(l => { m[l.id] = l.titulo; });
    return m;
  }, [catalogo]);
  const libroSeleccionado = seleccionado ? opcionsCatalogo.find(o => o.id === seleccionado) : null;
  const esLibro = libroSeleccionado && libroSeleccionado.total_estudos;

  async function engadir(e) {
    e.preventDefault();
    const maxOrde = itens.length ? Math.max(...itens.map(i=>i.orde)) : 0;
    if (modo === "catalogo" && esLibro) {
      const numeros = [...new Set(
        numerosEstudo.split(/[,\s]+/).map(n => parseInt(n,10)).filter(n => n >= 1 && n <= esLibro)
      )];
      if (!numeros.length) return;
      const filas = numeros.map((n, i) => ({
        matricula_id: matriculaId, trimestre, tipo, repertorio_xeral_id: seleccionado,
        numero_estudo: n, orde: maxOrde + i + 1,
      }));
      const { error } = await sb.from("repertorio_asignado").insert(filas);
      if (error) { aviso(error.message, "erro"); return; }
    } else {
      const payload = { matricula_id: matriculaId, trimestre, tipo, orde: maxOrde + 1 };
      if (modo === "catalogo") {
        if (!seleccionado) return;
        payload.repertorio_xeral_id = seleccionado;
      } else {
        if (!textoLibre.trim()) return;
        payload.texto_libre = textoLibre.trim();
      }
      const { error } = await sb.from("repertorio_asignado").insert(payload);
      if (error) { aviso(error.message, "erro"); return; }
    }
    setSeleccionado(""); setNumerosEstudo(""); setTextoLibre(""); setMostrarAdd(false);
    onCambio();
  }
  async function quitar(id) {
    await gardarSeguro(sb.from("repertorio_asignado").delete().eq("id", id), "repertorio_asignado");
    onCambio();
  }
  async function mover(item, dir) {
    const i = itens.findIndex(x => x.id === item.id);
    const j = i + dir;
    if (j < 0 || j >= itens.length) return;
    const outro = itens[j];
    await gardarSeguro(sb.from("repertorio_asignado").update({ orde: outro.orde }).eq("id", item.id), "repertorio_asignado");
    await gardarSeguro(sb.from("repertorio_asignado").update({ orde: item.orde }).eq("id", outro.id), "repertorio_asignado");
    onCambio();
  }

  async function alternarCompletada(item) {
    await gardarSeguro(sb.from("repertorio_asignado").update({ completada: !item.completada }).eq("id", item.id), "repertorio_asignado");
    onCambio();
  }
  async function alternarAcompanamento(item) {
    await gardarSeguro(sb.from("repertorio_asignado").update({ necesita_acompanamento: !item.necesita_acompanamento }).eq("id", item.id), "repertorio_asignado");
    onCambio();
  }
  async function alternarAudicion(item) {
    await gardarSeguro(sb.from("repertorio_asignado").update({ audicion: !item.audicion }).eq("id", item.id), "repertorio_asignado");
    onCambio();
  }

  return (
    <div className="grupo-tipo card">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <h4 style={{ margin: 0 }}>{tipo}</h4>
        {itens.length > 1 && (
          <button type="button" className="btn btn-ghost" style={{ fontSize: 11, padding: "3px 8px" }} onClick={()=>setOrdenando(o=>!o)}>
            {ordenando ? "Feito" : "Ordenar"}
          </button>
        )}
      </div>
      {itens.length === 0 && <div className="field-note">Sen obras asignadas.</div>}
      {itens.map((item,i) => {
        const xeral = item.repertorio_xeral_id ? catalogo.find(o=>o.id===item.repertorio_xeral_id) : null;
        return (
          <FilaEliminable key={item.id} id={item.id} abertaId={abertaId} onAbrirSwipe={setAbertaId} onEliminar={()=>quitar(item.id)}>
          <div className="obra-row">
            {ordenando && (
              <div className="reordenar">
                <button type="button" title="Subir esta obra" onClick={()=>mover(item,-1)} disabled={i===0}>▲</button>
                <button type="button" title="Baixar esta obra" onClick={()=>mover(item,1)} disabled={i===itens.length-1}>▼</button>
              </div>
            )}
            <div style={{ flex: 1, minWidth: 0 }}>
              <div className="titulo" style={item.completada ? { textDecoration: "line-through", color: "var(--sepia)" } : undefined}>
                {xeral ? tituloConNumero(xeral.titulo, item.numero_estudo, item.tipo) : item.texto_libre}
              </div>
              {xeral && xeral.autor && <div className="autor">{xeral.autor}</div>}
              {item.completada && <span className="chip" style={{ background: "#e8f5ed", color: "var(--verde)" }}>Completada</span>}
              {item.necesita_acompanamento && <span className="chip" style={{ background: "#f3e8fd", color: "#7a3bc4" }}>Acompañamento</span>}
              {item.audicion && <span className="chip" style={{ background: "#fdeee0", color: "#b5620a" }}>Audición</span>}
            </div>
            {xeral && xeral.pdf_path && (
              <a className="pdf-link" href={urlPdfRepertorio(xeral.pdf_path)} target="_blank" rel="noopener noreferrer">📄</a>
            )}
            <button className="btn btn-ghost" style={{ padding: "3px 8px", fontSize: 11.5 }} onClick={()=>setHistorialAberto(item)}>
              Historial
            </button>
            <button className="btn btn-ghost" style={{ padding: "3px 8px", fontSize: 11.5, color: item.necesita_acompanamento ? "#7a3bc4" : undefined }}
              onClick={()=>alternarAcompanamento(item)}>
              {item.necesita_acompanamento ? "✓ Acompañamento" : "Necesita acompañamento"}
            </button>
            <button className="btn btn-ghost" style={{ padding: "3px 8px", fontSize: 11.5, color: item.audicion ? "#b5620a" : undefined }}
              onClick={()=>alternarAudicion(item)}>
              {item.audicion ? "✓ Audición" : "Audición"}
            </button>
            <button className="btn btn-ghost" style={{ padding: "3px 8px", fontSize: 11.5 }} onClick={()=>alternarCompletada(item)}>
              {item.completada ? "Reabrir" : "Completada"}
            </button>
          </div>
          </FilaEliminable>
        );
      })}

      {mostrarAdd ? (
        <form onSubmit={engadir} style={{ marginTop: 10, borderTop: "1px solid var(--crema)", paddingTop: 10 }}>
          <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
            <button type="button" className={modo==="catalogo" ? "btn btn-primary" : "btn"} style={{ fontSize: 12, padding: "5px 10px" }} onClick={()=>setModo("catalogo")}>Do repertorio xeral</button>
            <button type="button" className={modo==="man" ? "btn btn-primary" : "btn"} style={{ fontSize: 12, padding: "5px 10px" }} onClick={()=>setModo("man")}>Escribir a man</button>
          </div>
          {modo === "catalogo" ? (
            <React.Fragment>
              <select className="field" value={seleccionado} onChange={e=>{ setSeleccionado(e.target.value); setNumerosEstudo(""); }}>
                <option value="">— Selecciona unha obra —</option>
                {opcionsCatalogo.map(o => (
                  <option key={o.id} value={o.id}>
                    {o.titulo}{o.autor ? ` — ${o.autor}` : ""}{o.total_estudos ? (TIPOS_MOVEMENTO.includes(tipo) ? ` (${o.total_estudos} movementos)` : ` (${o.total_estudos} estudos)`) : ""}{o.libro_id && librosPorId[o.libro_id] ? ` [${librosPorId[o.libro_id]}]` : ""}
                  </option>
                ))}
              </select>
              {esLibro && (
                <div style={{ marginTop: 8 }}>
                  <label>
                    {TIPOS_MOVEMENTO.includes(tipo)
                      ? `Movemento(s) (1–${esLibro}) — pode ser máis dun, separados por coma`
                      : `Número(s) de estudo (1–${esLibro}) — pode ser máis dun, separados por coma`}
                  </label>
                  <input type="text" placeholder={TIPOS_MOVEMENTO.includes(tipo) ? "p.ex. 1, 2" : "p.ex. 12, 15, 20"} value={numerosEstudo} onChange={e=>setNumerosEstudo(e.target.value)} />
                </div>
              )}
            </React.Fragment>
          ) : (
            <input type="text" placeholder="Nome da obra" value={textoLibre} onChange={e=>setTextoLibre(e.target.value)} />
          )}
          <div className="row-actions">
            <button type="button" className="btn" onClick={()=>setMostrarAdd(false)}>Cancelar</button>
            <button className="btn btn-primary">Engadir</button>
          </div>
        </form>
      ) : (
        <button className="btn" style={{ marginTop: 10, fontSize: 12.5 }} onClick={()=>setMostrarAdd(true)}>+ Engadir obra</button>
      )}
      {historialAberto && (
        <HistorialObra
          titulo={(() => {
            const xeral = historialAberto.repertorio_xeral_id ? catalogo.find(o=>o.id===historialAberto.repertorio_xeral_id) : null;
            return xeral ? tituloConNumero(xeral.titulo, historialAberto.numero_estudo, historialAberto.tipo) : historialAberto.texto_libre;
          })()}
          matriculaId={matriculaId} repertorioAsignadoId={historialAberto.id}
          onClose={()=>setHistorialAberto(null)}
        />
      )}
    </div>
  );
}

const TRIMESTRES_REPERTORIO = [
  { n: 1, label: "1º Trimestre" }, { n: 2, label: "2º Trimestre" },
  { n: 3, label: "3º Trimestre" }, { n: 4, label: "Verán" },
];

function TabRepertorio({ matriculaId, alumno, matricula }) {
  const [trimestre, setTrimestre] = useState(1);
  const [itens, setItens] = useState(null);
  const [catalogo, setCatalogo] = useState([]);
  const [xerandoPdf, setXerandoPdf] = useState(false);

  async function cargar() {
    setItens(null);
    const [{ data: asignado, error }, { data: xeral }] = await Promise.all([
      sb.from("repertorio_asignado").select("*").eq("matricula_id", matriculaId).eq("trimestre", trimestre).order("orde"),
      sb.from("repertorio_xeral").select("*").order("tipo").order("orde"),
    ]);
    if (error) { aviso(error.message, "erro"); return; }
    setItens(asignado);
    setCatalogo(xeral || []);
  }
  useEffect(() => { cargar(); }, [matriculaId, trimestre]);

  if (itens === null) return <div className="empty">Cargando…</div>;

  function xerarPdf() {
    setXerandoPdf(true);
    const trimestreLabel = TRIMESTRES_REPERTORIO.find(t=>t.n===trimestre).label;
    const itensPorTipo = {};
    TIPOS_REPERTORIO.forEach(tipo => {
      itensPorTipo[tipo] = itens.filter(i=>i.tipo===tipo).map(item => {
        const xeral = item.repertorio_xeral_id ? catalogo.find(o=>o.id===item.repertorio_xeral_id) : null;
        return xeral ? `${tituloConNumero(xeral.titulo, item.numero_estudo, tipo)}${xeral.autor ? " — "+xeral.autor : ""}` : item.texto_libre;
      });
    });
    const ficheiro = exportarRepertorioTrimestrePDF(alumno, matricula, trimestreLabel, itensPorTipo);
    abrirMailto(alumno, ficheiro, `Repertorio — ${trimestreLabel} — ${alumno.nome} ${alumno.apelidos||""}`);
    setXerandoPdf(false);
  }

  return (
    <div>
      <div className="tabs" style={{ position: "static", background: "transparent", borderBottom: "none", padding: 0, marginBottom: 10 }}>
        {TRIMESTRES_REPERTORIO.map(t => (
          <button key={t.n} className={trimestre===t.n?"active":""} onClick={()=>setTrimestre(t.n)}>{t.label}</button>
        ))}
      </div>
      {TIPOS_REPERTORIO.map(tipo => (
        <SeccionRepertorioTipo key={tipo} matriculaId={matriculaId} trimestre={trimestre} tipo={tipo}
          catalogo={catalogo} itens={itens.filter(i=>i.tipo===tipo)} onCambio={cargar} />
      ))}
      {itens.length > 0 && (
        <button className="btn btn-block" disabled={xerandoPdf} onClick={xerarPdf}>
          {xerandoPdf ? "Xerando…" : "📄 PDF deste repertorio + Email"}
        </button>
      )}
    </div>
  );
}

// ============================================================
// TAB: Clases
// ============================================================
function SelectorOpcionsPDF({ titulo, onCancelar, onConfirmar, mostrarFaltas }) {
  const [op, setOp] = useState({ inicioClase: true, obraProgreso: true, tarefas: true, notas: true, faltas: true });
  const [xerando, setXerando] = useState(false);
  function toggle(k) { setOp(o => ({ ...o, [k]: !o[k] })); }
  const opcions = [
    ["inicioClase", "Inicio da clase"], ["obraProgreso", "Obra / Progreso"],
    ["tarefas", "Tarefas"], ["notas", "Notas"],
  ];
  if (mostrarFaltas) opcions.push(["faltas", "Faltas"]);

  return (
    <Modal title={titulo} onClose={onCancelar}>
      <div style={{ display: "flex", flexDirection: "column", gap: 10, margin: "8px 0 18px" }}>
        {opcions.map(([k,label]) => (
          <label key={k} style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 14 }}>
            <input type="checkbox" checked={op[k]} onChange={()=>toggle(k)} style={{ width: 18, height: 18 }} />
            {label}
          </label>
        ))}
      </div>
      <div className="row-actions">
        <button className="btn" onClick={onCancelar}>Cancelar</button>
        <button className="btn btn-primary" disabled={xerando}
          onClick={async ()=>{ setXerando(true); await onConfirmar(op); }}>
          {xerando ? "Xerando…" : "Xerar PDF e enviar"}
        </button>
      </div>
    </Modal>
  );
}

function TarxetaClase({ fila, obrasDispoñibles, pesos, alumno, expandida, onExpandir, onGardado, onCambio }) {
  const [data, setData] = useState(fila.data || "");
  const [falta, setFalta] = useState(fila.falta || false);
  const [motivoFalta, setMotivoFalta] = useState(fila.motivo_falta || "");
  const [inicioClase, setInicioClase] = useState(fila.inicio_clase || "");
  const [observacions, setObservacions] = useState(fila.observacions || "");
  const [tarefas, setTarefas] = useState(fila.tarefas || "");
  const [criterios, setCriterios] = useState(() => {
    const c = {};
    pesos.forEach(p => { c[p.key] = fila[p.key] ?? ""; });
    return c;
  });
  const [obras, setObras] = useState(fila.obras || []);
  const [mostrarPdf, setMostrarPdf] = useState(false);
  const [gardando, setGardando] = useState(false);

  function cambiarCriterio(key, v) { setCriterios(c => ({ ...c, [key]: v })); }
  async function gardarCampo(campos) {
    await gardarSeguro(sb.from("clases").update(campos).eq("id", fila.id), "clases");
  }
  async function gardarCriterio() {
    const notas = {};
    pesos.forEach(p => { notas[p.key] = criterios[p.key]; });
    await gardarCampo({ notas });
  }
  async function alternarFalta() {
    const novo = !falta;
    setFalta(novo);
    await gardarCampo({ falta: novo });
  }
  async function alternarObra(obraAsig) {
    const existente = obras.find(o => o.repertorio_asignado_id === obraAsig.id);
    if (existente) {
      await gardarSeguro(sb.from("clases_repertorio").delete().eq("id", existente.id), "clases_repertorio");
      setObras(obras.filter(o => o.id !== existente.id));
    } else {
      const { data: nova, error } = await sb.from("clases_repertorio").insert({
        clase_id: fila.id, repertorio_asignado_id: obraAsig.id, progreso: "",
      }).select().single();
      if (error) { aviso(error.message, "erro"); return; }
      setObras([...obras, { id: nova.id, repertorio_asignado_id: obraAsig.id, progreso: "", titulo: obraAsig.titulo, autor: obraAsig.autor }]);
    }
  }
  function cambiarProgreso(idCr, valor) { setObras(obras.map(o => o.id === idCr ? { ...o, progreso: valor } : o)); }
  async function borrar() {
    if (!confirm("Eliminar esta clase?")) return;
    await gardarSeguro(sb.from("clases").delete().eq("id", fila.id), "clases");
    onCambio();
  }

  const estado = estadoFila(criterios, pesos);
  const media = estado === "completa" ? mediaFila(criterios, pesos) : null;

  async function gardarTodo() {
    setGardando(true);
    const notas = {};
    pesos.forEach(p => { notas[p.key] = criterios[p.key]; });
    await gardarSeguro(sb.from("clases").update({ data, falta, motivo_falta: motivoFalta, inicio_clase: inicioClase, observacions, tarefas, notas }).eq("id", fila.id), "clases");
    await Promise.all(obras.map(o => sb.from("clases_repertorio").update({ progreso: o.progreso }).eq("id", o.id)));
    setGardando(false);
    onGardado();
  }

  async function xerarPdf(opcions) {
    const filaParaPdf = { ...criterios, data, inicio_clase: inicioClase, tarefas };
    const ficheiro = exportarClasePDF(alumno, filaParaPdf, obras, pesos, opcions);
    abrirMailto(alumno, ficheiro, `Clase do ${data} — ${alumno.nome} ${alumno.apelidos||""}`);
    setMostrarPdf(false);
  }

  if (!expandida) {
    return (
      <div className="alumno-row" onClick={onExpandir} style={falta ? { borderColor: "var(--rojo)", background: "#fceae8" } : undefined}>
        {falta && <div className="clase-avatar">🚫</div>}
        <div className="info">
          <div className="nome">{fila.data ? formatarDataCurta(fila.data) : "(sen data)"}</div>
          {!falta && obras.length > 0 && <div className="meta">{obras.length} obra{obras.length>1?"s":""} traballada{obras.length>1?"s":""}</div>}
        </div>
        {falta && <span className="tag" style={{ background: "#fceae8", color: "var(--rojo)" }}>Falta</span>}
        {!falta && media !== null && <span className="tag" style={media < 5 ? { background: "#fceae8", color: "var(--rojo)" } : { background: "#e8f5ed", color: "var(--verde)" }}>{fmt(media)}</span>}
      </div>
    );
  }

  return (
    <div className="card" style={falta ? { borderColor: "var(--rojo)", background: "#fceae8" } : undefined}>
      <div className="clase-cabeceira">
        <input type="date" value={data} onChange={e=>setData(e.target.value)} onBlur={()=>gardarCampo({ data })} />
        <label className="clase-falta-switch" style={falta ? { color: "var(--rojo)" } : undefined}>
          Falta
          <label className="toggle" style={{ marginLeft: 2 }}>
            <input type="checkbox" checked={falta} onChange={alternarFalta} />
            <span className="slider"></span>
          </label>
        </label>
      </div>

      {falta ? (
        <div className="clase-seccion" style={{ borderLeftColor: "var(--rojo)" }}>
          <div className="clase-seccion-titulo">🚫 Falta</div>
          <label>Motivo (opcional)</label>
          <input type="text" value={motivoFalta} onChange={e=>setMotivoFalta(e.target.value)} onBlur={()=>gardarCampo({ motivo_falta: motivoFalta })} />
        </div>
      ) : (
        <React.Fragment>
          <div className="clase-seccion">
            <div className="clase-seccion-titulo">Inicio da clase</div>
            <textarea value={inicioClase} onChange={e=>setInicioClase(e.target.value)} onBlur={()=>gardarCampo({ inicio_clase: inicioClase })} style={{ minHeight: 70 }}></textarea>
          </div>

          <div className="clase-seccion">
            <div className="clase-seccion-titulo">Repertorio traballado hoxe</div>
            {obrasDispoñibles.length === 0 && <div className="field-note">Aínda non hai repertorio asignado para este trimestre.</div>}
            <div>
              {obrasDispoñibles.map(ob => {
                const activa = obras.some(o => o.repertorio_asignado_id === ob.id);
                return (
                  <button type="button" key={ob.id}
                    className="chip" style={{ cursor: "pointer", border: "none",
                      background: activa ? "var(--azul-cmus)" : "#fff", color: activa ? "#fff" : "var(--azul-xunta)" }}
                    onClick={()=>alternarObra(ob)}>
                    {ob.titulo}{ob.autor ? ` — ${ob.autor}` : ""}
                  </button>
                );
              })}
            </div>
          </div>

          {obras.map(o => (
            <div key={o.id} className="clase-seccion obra">
              <div className="clase-seccion-titulo">Progreso — {o.titulo}</div>
              <textarea value={o.progreso} onChange={e=>cambiarProgreso(o.id, e.target.value)}
                onBlur={()=>sb.from("clases_repertorio").update({ progreso: o.progreso }).eq("id", o.id)} style={{ minHeight: 70 }}></textarea>
            </div>
          ))}

          <div className="clase-seccion" style={{ borderLeftColor: "var(--oro)" }}>
            <div className="clase-seccion-titulo" style={{ color: "#8a6d1f" }}>Tarefas</div>
            <textarea value={tarefas} onChange={e=>setTarefas(e.target.value)} onBlur={()=>gardarCampo({ tarefas })} style={{ minHeight: 70 }}></textarea>
          </div>

          <div className="clase-seccion" style={{ borderLeftColor: "var(--sepia)" }}>
            <div className="clase-seccion-titulo" style={{ color: "var(--sepia)" }}>Observacións (notas privadas — nunca se envían)</div>
            <textarea value={observacions} onChange={e=>setObservacions(e.target.value)} onBlur={()=>gardarCampo({ observacions })} style={{ minHeight: 70 }}></textarea>
          </div>

          <label>Criterios de avaliación</label>
          <div className="grid2">
            {pesos.map(p => (
              <div key={p.key} className="card" style={{ padding: "10px 12px" }}>
                <div className="slabel" style={{ marginBottom: 6 }}>{p.label} <span className="peso">{Math.round(p.peso*100)}%</span></div>
                <input type="number" step="0.1" min="0" max="10" className={notaClass(criterios[p.key])}
                  value={criterios[p.key]} onChange={e=>cambiarCriterio(p.key, e.target.value)} onBlur={gardarCriterio} style={{ width: "100%" }} />
              </div>
            ))}
          </div>
          {estado === "incompleta" && <div className="field-note" style={{ color: "var(--rojo)" }}>⚠ Faltan criterios por encher — este día non contará na media até que os completes todos.</div>}
          {estado === "completa" && <div className="field-note" style={{ color: "var(--verde)" }}>Media do día: {fmt(media)}</div>}
        </React.Fragment>
      )}

      <div className="row-actions">
        <button className="btn" style={{ fontSize: 12.5, padding: "6px 12px" }} onClick={()=>setMostrarPdf(true)}>PDF + Email á familia</button>
        <button className="btn btn-danger" style={{ fontSize: 12.5, padding: "6px 12px" }} onClick={borrar}>Eliminar</button>
        <button className="btn btn-primary" style={{ fontSize: 12.5, padding: "6px 12px", marginLeft: "auto" }} disabled={gardando} onClick={gardarTodo}>
          {gardando ? "Gardando…" : "Gardar"}
        </button>
      </div>

      {mostrarPdf && <SelectorOpcionsPDF titulo="Xerar PDF da clase" onCancelar={()=>setMostrarPdf(false)} onConfirmar={xerarPdf} />}
    </div>
  );
}

function TabClases({ matriculaId, grao, alumno, matricula }) {
  const [trimestre, setTrimestre] = useState(1);
  const [filas, setFilas] = useState(null);
  const [obrasAsignadas, setObrasAsignadas] = useState([]);
  const [mostrarPdfTrimestre, setMostrarPdfTrimestre] = useState(false);
  const [expandidaId, setExpandidaId] = useState(null);
  const pesos = PESOS_ACTUAIS[grao];

  async function cargar(idParaAbrir) {
    setFilas(null);
    const [{ data: clasesData, error }, { data: asignadoData }] = await Promise.all([
      sb.from("clases")
        .select("*, clases_repertorio(*, repertorio_asignado(id, texto_libre, numero_estudo, tipo, repertorio_xeral(titulo,autor)))")
        .eq("matricula_id", matriculaId).eq("trimestre", trimestre)
        .order("data", { ascending: true })
        .order("created_at", { foreignTable: "clases_repertorio", ascending: true }),
      sb.from("repertorio_asignado")
        .select("*, repertorio_xeral(titulo,autor)")
        .eq("matricula_id", matriculaId).eq("trimestre", trimestre).eq("completada", false).order("orde"),
    ]);
    if (error) { aviso(error.message, "erro"); return; }
    const procesadas = (clasesData||[]).map(c => ({
      ...c, ...(c.notas || {}),
      obras: (c.clases_repertorio||[]).map(cr => ({
        id: cr.id, repertorio_asignado_id: cr.repertorio_asignado_id, progreso: cr.progreso || "",
        titulo: tituloConNumero(cr.repertorio_asignado?.repertorio_xeral?.titulo || cr.repertorio_asignado?.texto_libre || "(obra eliminada)", cr.repertorio_asignado?.numero_estudo, cr.repertorio_asignado?.tipo),
        autor: cr.repertorio_asignado?.repertorio_xeral?.autor || null,
      })),
    }));
    setFilas(procesadas);
    setObrasAsignadas((asignadoData||[]).map(a => ({
      id: a.id, titulo: tituloConNumero(a.repertorio_xeral?.titulo || a.texto_libre || "?", a.numero_estudo, a.tipo), autor: a.repertorio_xeral?.autor || null,
    })));
    if (idParaAbrir !== undefined) {
      setExpandidaId(idParaAbrir);
    } else {
      setExpandidaId(procesadas.length ? procesadas[procesadas.length - 1].id : null);
    }
  }
  useEffect(() => { cargar(); }, [matriculaId, trimestre]);

  async function engadirFila() {
    const { data, error } = await sb.from("clases").insert({
      matricula_id: matriculaId, trimestre, data: new Date().toISOString().slice(0,10), notas: {},
    }).select().single();
    if (error) { aviso(error.message, "erro"); return; }
    cargar(data.id);
  }

  async function xerarPdfTrimestre(opcions) {
    const obrasMapa = {};
    filas.filter(f=>!f.falta).forEach(f => {
      f.obras.forEach(o => {
        if (!o.progreso) return;
        const chave = o.titulo + (o.autor ? ` — ${o.autor}` : "");
        if (!obrasMapa[chave]) obrasMapa[chave] = [];
        obrasMapa[chave].push({ data: f.data, progreso: o.progreso });
      });
    });
    const obrasAgrupadas = Object.keys(obrasMapa).map(titulo => ({ titulo, entradas: obrasMapa[titulo] }));
    const inicioClasePorData = filas.filter(f=>!f.falta && f.inicio_clase).map(f => ({ data: f.data, texto: f.inicio_clase }));
    const tarefasPorData = filas.filter(f=>!f.falta && f.tarefas).map(f => ({ data: f.data, texto: f.tarefas }));
    const faltas = filas.filter(f=>f.falta).map(f => ({ data: f.data, motivo: f.motivo_falta }));

    const mClases = mediaGrupo(filas, pesos, filaCompleta);
    const [{ data: audiData }, { data: altData }] = await Promise.all([
      sb.from("audicions").select("*").eq("matricula_id", matriculaId).eq("trimestre", trimestre),
      sb.from("avaliacion_alternativa").select("*").eq("matricula_id", matriculaId).eq("trimestre", trimestre).maybeSingle(),
    ]);
    const hayAudicion = (audiData||[]).some(a => filaTenDatos(a, PESOS_AUDICION));
    const mAudi = hayAudicion ? mediaGrupo(audiData||[], PESOS_AUDICION) : 0;
    const cualificacion = altData
      ? { alternativa: true, final: mediaAlternativa(altData) }
      : { alternativa: false, clases: mClases, audicion: mAudi, hayAudicion, final: hayAudicion ? (mClases*0.7 + mAudi*0.3) : mClases };

    const ficheiro = exportarResumoTrimestralPDF(alumno, matricula, trimestre, { obrasAgrupadas, inicioClasePorData, tarefasPorData, cualificacion, faltas }, opcions);
    abrirMailto(alumno, ficheiro, `Resumo ${trimestre}º trimestre — ${alumno.nome} ${alumno.apelidos||""}`);
    setMostrarPdfTrimestre(false);
  }

  if (filas === null) return <div className="empty">Cargando…</div>;
  const media = mediaGrupo(filas, pesos, filaCompleta);

  return (
    <div>
      <div className="tabs" style={{ position: "static", background: "transparent", borderBottom: "none", padding: 0, marginBottom: 10 }}>
        {TRIMESTRES.map(t => (
          <button key={t.n} className={trimestre===t.n?"active":""} onClick={()=>setTrimestre(t.n)}>{t.label}</button>
        ))}
      </div>

      {filas.map(fila => (
        <TarxetaClase key={fila.id} fila={fila} obrasDispoñibles={obrasAsignadas} pesos={pesos} alumno={alumno}
          expandida={expandidaId === fila.id}
          onExpandir={()=>setExpandidaId(fila.id)}
          onGardado={()=>cargar(null)}
          onCambio={()=>cargar(null)} />
      ))}

      <button className="btn" onClick={engadirFila}>+ Engadir clase</button>

      <div className="summary">
        <div className="box"><div className="num">{fmt(media)}</div><div className="lbl">Media clases (70%) · {trimestre}º trim.</div></div>
      </div>

      <button className="btn btn-block" style={{ marginTop: 14 }} onClick={()=>setMostrarPdfTrimestre(true)}>📄 Xerar resumo do trimestre</button>
      {mostrarPdfTrimestre && (
        <SelectorOpcionsPDF titulo={`Resumo do ${trimestre}º trimestre`} mostrarFaltas onCancelar={()=>setMostrarPdfTrimestre(false)} onConfirmar={xerarPdfTrimestre} />
      )}
    </div>
  );
}

function FilaFalta({ falta, onCambio }) {
  const [subida, setSubida] = useState(falta.falta_subida_centros_net || false);
  async function alternar() {
    const novo = !subida;
    setSubida(novo);
    await gardarSeguro(sb.from("clases").update({ falta_subida_centros_net: novo }).eq("id", falta.id), "clases");
    onCambio && onCambio();
  }
  return (
    <div className="titoria-item">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
        <div>
          <strong>{formatarDataCurta(falta.data)}</strong>
          {falta.motivo_falta && <div style={{ fontSize: 13, color: "var(--tinta-suave)", marginTop: 2 }}>{falta.motivo_falta}</div>}
        </div>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11.5, color: "var(--sepia)", whiteSpace: "nowrap" }}>
          Centros Net
          <input type="checkbox" checked={subida} onChange={alternar} style={{ width: 16, height: 16 }} />
        </label>
      </div>
    </div>
  );
}

function TabFaltas({ matriculaId }) {
  const [porTrimestre, setPorTrimestre] = useState(null);
  async function cargar() {
    const { data, error } = await sb.from("clases").select("*").eq("matricula_id", matriculaId).eq("falta", true).order("data");
    if (error) { aviso(error.message, "erro"); return; }
    const agrupado = { 1: [], 2: [], 3: [] };
    (data||[]).forEach(f => { if (agrupado[f.trimestre]) agrupado[f.trimestre].push(f); });
    setPorTrimestre(agrupado);
  }
  useEffect(() => { cargar(); }, [matriculaId]);

  if (porTrimestre === null) return <div className="empty">Cargando…</div>;
  const total = [1,2,3].reduce((s,t) => s + porTrimestre[t].length, 0);

  return (
    <div>
      <div className="summary" style={{ marginBottom: 14 }}>
        <div className="box"><div className="num">{total}</div><div className="lbl">Faltas totais no curso</div></div>
      </div>
      {[1,2,3].map(t => {
        const xustificadas = porTrimestre[t].filter(f => f.motivo_falta && f.motivo_falta.trim());
        const senXustificar = porTrimestre[t].filter(f => !f.motivo_falta || !f.motivo_falta.trim());
        return (
          <div className="card" key={t}>
            <h4 style={{ marginTop: 0 }}>{t}º Trimestre <span style={{ color: "var(--sepia)", fontWeight: 400 }}>({porTrimestre[t].length})</span></h4>
            {porTrimestre[t].length === 0 && <div className="field-note">Sen faltas.</div>}
            {xustificadas.length > 0 && (
              <React.Fragment>
                <div className="clase-seccion-titulo" style={{ color: "var(--verde)", marginTop: 10 }}>Xustificadas ({xustificadas.length})</div>
                {xustificadas.map(f => <FilaFalta key={f.id} falta={f} />)}
              </React.Fragment>
            )}
            {senXustificar.length > 0 && (
              <React.Fragment>
                <div className="clase-seccion-titulo" style={{ color: "var(--rojo)", marginTop: 10 }}>Sen xustificar ({senXustificar.length})</div>
                {senXustificar.map(f => <FilaFalta key={f.id} falta={f} />)}
              </React.Fragment>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ============================================================
// TAB: Audicións
// ============================================================
function TarxetaAudicion({ fila, obrasDispoñibles, onCambio }) {
  const [data, setData] = useState(fila.data || "");
  const [observacions, setObservacions] = useState(fila.observacions || "");
  const [criterios, setCriterios] = useState(() => {
    const c = {};
    PESOS_AUDICION.forEach(p => { c[p.key] = fila[p.key] ?? ""; });
    return c;
  });
  const [obras, setObras] = useState(fila.obras || []);

  async function gardarPrincipal(campos) {
    await gardarSeguro(sb.from("audicions").update(campos).eq("id", fila.id), "audicions");
  }
  function cambiarCriterio(key, v) { setCriterios(c => ({ ...c, [key]: v })); }
  async function gardarCriterios() {
    const campos = {};
    PESOS_AUDICION.forEach(p => { campos[p.key] = criterios[p.key] === "" ? null : criterios[p.key]; });
    await gardarPrincipal(campos);
  }
  async function alternarObra(obraAsig) {
    const existente = obras.find(o => o.repertorio_asignado_id === obraAsig.id);
    if (existente) {
      await gardarSeguro(sb.from("audicions_repertorio").delete().eq("id", existente.id), "audicions_repertorio");
      setObras(obras.filter(o => o.id !== existente.id));
    } else {
      const { data: nova, error } = await sb.from("audicions_repertorio").insert({
        audicion_id: fila.id, repertorio_asignado_id: obraAsig.id,
      }).select().single();
      if (error) { aviso(error.message, "erro"); return; }
      setObras([...obras, { id: nova.id, repertorio_asignado_id: obraAsig.id, titulo: obraAsig.titulo }]);
    }
  }
  async function borrar() {
    if (!confirm("Eliminar esta audición?")) return;
    await gardarSeguro(sb.from("audicions").delete().eq("id", fila.id), "audicions");
    onCambio();
  }

  const estado = estadoFila(criterios, PESOS_AUDICION);
  const media = estado === "completa" ? mediaFila(criterios, PESOS_AUDICION) : null;

  return (
    <div className="card">
      <div className="clase-cabeceira">
        <input type="date" value={data} onChange={e=>setData(e.target.value)} onBlur={()=>gardarPrincipal({ data })} />
        <button className="btn btn-danger" style={{ fontSize: 12, padding: "5px 10px" }} onClick={borrar}>Eliminar</button>
      </div>

      <div className="clase-seccion">
        <div className="clase-seccion-titulo">Repertorio</div>
        {obrasDispoñibles.length === 0 && <div className="field-note">Aínda non hai repertorio asignado para este trimestre.</div>}
        <div>
          {obrasDispoñibles.map(ob => {
            const activa = obras.some(o => o.repertorio_asignado_id === ob.id);
            return (
              <button type="button" key={ob.id}
                className="chip" style={{ cursor: "pointer", border: "none",
                  background: activa ? "var(--azul-cmus)" : "#fff", color: activa ? "#fff" : "var(--azul-xunta)" }}
                onClick={()=>alternarObra(ob)}>
                {ob.titulo}{ob.autor ? ` — ${ob.autor}` : ""}
              </button>
            );
          })}
        </div>
      </div>

      <div className="clase-seccion">
        <div className="clase-seccion-titulo">Observacións</div>
        <textarea value={observacions} onChange={e=>setObservacions(e.target.value)} onBlur={()=>gardarPrincipal({ observacions })} style={{ minHeight: 130 }}></textarea>
      </div>

      <label>Criterios</label>
      <div className="grid2">
        {PESOS_AUDICION.map(p => (
          <div key={p.key} className="card" style={{ padding: "10px 12px" }}>
            <div className="slabel" style={{ marginBottom: 6 }}>{p.label} <span className="peso">{Math.round(p.peso*100)}%</span></div>
            <input type="number" step="0.1" min="0" max="10" className={notaClass(criterios[p.key])}
              value={criterios[p.key]} onChange={e=>cambiarCriterio(p.key, e.target.value)} onBlur={gardarCriterios} style={{ width: "100%" }} />
          </div>
        ))}
      </div>
      {estado === "completa" && <div className="field-note" style={{ color: "var(--verde)" }}>Media da audición: {fmt(media)}</div>}
    </div>
  );
}

function TabAudicions({ matriculaId }) {
  const [trimestre, setTrimestre] = useState(1);
  const [filas, setFilas] = useState(null);
  const [obrasAsignadas, setObrasAsignadas] = useState([]);

  async function cargar() {
    setFilas(null);
    const [{ data: audiData, error }, { data: asignadoData }] = await Promise.all([
      sb.from("audicions").select("*, audicions_repertorio(*, repertorio_asignado(texto_libre, numero_estudo, tipo, repertorio_xeral(titulo)))")
        .eq("matricula_id", matriculaId).eq("trimestre", trimestre).order("data", { ascending: true }),
      sb.from("repertorio_asignado").select("*, repertorio_xeral(titulo,autor)")
        .eq("matricula_id", matriculaId).eq("trimestre", trimestre).eq("completada", false).order("tipo"),
    ]);
    if (error) { aviso(error.message, "erro"); return; }
    const procesadas = (audiData||[]).map(a => ({
      ...a,
      obras: (a.audicions_repertorio||[]).map(ar => ({
        id: ar.id, repertorio_asignado_id: ar.repertorio_asignado_id,
        titulo: tituloConNumero(ar.repertorio_asignado?.repertorio_xeral?.titulo || ar.repertorio_asignado?.texto_libre || "?", ar.repertorio_asignado?.numero_estudo, ar.repertorio_asignado?.tipo),
      })),
    }));
    setFilas(procesadas);
    setObrasAsignadas((asignadoData||[]).map(a => ({
      id: a.id, titulo: tituloConNumero(a.repertorio_xeral?.titulo || a.texto_libre || "?", a.numero_estudo, a.tipo), autor: a.repertorio_xeral?.autor || null,
    })));
  }
  useEffect(() => { cargar(); }, [matriculaId, trimestre]);

  async function engadirFila() {
    const { error } = await sb.from("audicions").insert({
      matricula_id: matriculaId, trimestre, data: new Date().toISOString().slice(0,10),
    });
    if (error) { aviso(error.message, "erro"); return; }
    cargar();
  }

  if (filas === null) return <div className="empty">Cargando…</div>;
  const media = mediaGrupo(filas, PESOS_AUDICION);

  return (
    <div>
      <div className="tabs" style={{ position: "static", background: "transparent", borderBottom: "none", padding: 0, marginBottom: 10 }}>
        {TRIMESTRES.map(t => (
          <button key={t.n} className={trimestre===t.n?"active":""} onClick={()=>setTrimestre(t.n)}>{t.label}</button>
        ))}
      </div>
      {filas.map(fila => (
        <TarxetaAudicion key={fila.id} fila={fila} obrasDispoñibles={obrasAsignadas} onCambio={cargar} />
      ))}
      <button className="btn" onClick={engadirFila}>+ Engadir audición</button>
      <div className="summary">
        <div className="box"><div className="num">{fmt(media)}</div><div className="lbl">Media audición (30%) · {trimestre}º trim.</div></div>
      </div>
    </div>
  );
}

// ============================================================
// TAB: Cualificacións (calculado, sen táboa propia)
// ============================================================
function useCualificacions(matriculaId, grao) {
  const [cualificacions, setCualificacions] = useState(null);
  useEffect(() => {
    let activo = true;
    async function cargar() {
      const [{ data: clases }, { data: audi }] = await Promise.all([
        sb.from("clases").select("*").eq("matricula_id", matriculaId),
        sb.from("audicions").select("*").eq("matricula_id", matriculaId),
      ]);
      if (!activo) return;
      const pesos = PESOS_ACTUAIS[grao];
      const clasesFlat = (clases||[]).map(c => ({ ...c, ...(c.notas || {}) }));
      const resultado = [1,2,3].map(t => {
        const filasClases = clasesFlat.filter(c => c.trimestre === t);
        const filasAudi = (audi||[]).filter(a => a.trimestre === t);
        const mClases = mediaGrupo(filasClases, pesos, filaCompleta);
        const hayAudicion = filasAudi.some(a => filaTenDatos(a, PESOS_AUDICION));
        const mAudi = hayAudicion ? mediaGrupo(filasAudi, PESOS_AUDICION) : 0;
        const final = hayAudicion ? (mClases*0.7 + mAudi*0.3) : mClases;
        return { trimestre: t, clases: mClases, audicion: mAudi, final, hayAudicion };
      });
      setCualificacions(resultado);
    }
    cargar();
    return () => { activo = false; };
  }, [matriculaId, grao]);
  return cualificacions;
}

const CRITERIOS_ALTERNATIVA = [
  { key: "afinacion", label: "Afinación" },
  { key: "ritmo", label: "Ritmo" },
  { key: "son", label: "Son" },
  { key: "musicalidade", label: "Musicalidade" },
];
function mediaAlternativa(alt) {
  return CRITERIOS_ALTERNATIVA.reduce((s,c) => s + (Number(alt[c.key]) || 0) * 0.25, 0);
}

function FilaAlternativa({ matriculaId, trimestre, alt, onCambio }) {
  const [f, setF] = useState({
    afinacion: alt.afinacion ?? "", ritmo: alt.ritmo ?? "", son: alt.son ?? "", musicalidade: alt.musicalidade ?? "",
    motivo: alt.motivo || "",
  });
  function cambiar(campo, valor) { setF(prev => ({ ...prev, [campo]: valor })); }
  async function gardar() {
    await gardarSeguro(sb.from("avaliacion_alternativa").update({
      motivo: f.motivo,
      afinacion: f.afinacion === "" ? null : f.afinacion,
      ritmo: f.ritmo === "" ? null : f.ritmo,
      son: f.son === "" ? null : f.son,
      musicalidade: f.musicalidade === "" ? null : f.musicalidade,
    }).eq("id", alt.id), "avaliación non continua");
    onCambio();
  }
  async function volverAContinua() {
    if (!confirm("Volver á avaliación continua neste trimestre? Pérdense estas notas.")) return;
    await gardarSeguro(sb.from("avaliacion_alternativa").delete().eq("id", alt.id), "avaliacion_alternativa");
    onCambio();
  }
  const media = mediaAlternativa(f);
  const hayDatos = CRITERIOS_ALTERNATIVA.some(c => f[c.key] !== "");

  return (
    <div className="card">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <strong>{trimestre}º avaliación — non continua</strong>
        <button className="btn btn-ghost" style={{ fontSize: 12, padding: "4px 8px" }} onClick={volverAContinua}>Volver a continua</button>
      </div>
      <div className="field-note">Proba única (afinación, ritmo, son e musicalidade — 25% cada unha)</div>
      <Campo label="Motivo (opcional)" value={f.motivo} onChange={e=>cambiar("motivo",e.target.value)} onBlur={gardar} />
      <div className="grid2">
        {CRITERIOS_ALTERNATIVA.map(c => (
          <div key={c.key}>
            <label>{c.label}</label>
            <input type="number" step="0.1" min="0" max="10" className={notaClass(f[c.key])}
              value={f[c.key]} onChange={e=>cambiar(c.key,e.target.value)} onBlur={gardar} />
          </div>
        ))}
      </div>
      <div className="summary">
        <div className="box"><div className="num">{hayDatos ? fmt(media) : "—"}</div><div className="lbl">Nota final (non continua)</div></div>
      </div>
    </div>
  );
}

function TabCualificacions({ matriculaId, cualificacions }) {
  const [alternativas, setAlternativas] = useState(null);
  async function cargarAlternativas() {
    const { data } = await sb.from("avaliacion_alternativa").select("*").eq("matricula_id", matriculaId);
    setAlternativas(data || []);
  }
  useEffect(() => { cargarAlternativas(); }, [matriculaId]);

  async function activarAlternativa(trimestre) {
    const { error } = await sb.from("avaliacion_alternativa").insert({ matricula_id: matriculaId, trimestre });
    if (error) { aviso(error.message, "erro"); return; }
    cargarAlternativas();
  }

  if (!cualificacions || alternativas === null) return <div className="empty">Cargando…</div>;

  return (
    <div>
      <div className="card">
        <div className="table-scroll">
          <table className="grid" style={{ minWidth: 420 }}>
            <thead><tr><th>Trimestre</th><th>Clases</th><th>Audición</th><th>Nota final</th></tr></thead>
            <tbody>
              {cualificacions.map(c => {
                const alt = alternativas.find(a => a.trimestre === c.trimestre);
                if (alt) {
                  const media = mediaAlternativa(alt);
                  return (
                    <tr key={c.trimestre}>
                      <td>{c.trimestre}º avaliación</td>
                      <td colSpan={2} style={{ fontStyle: "italic", color: "var(--sepia)" }}>Avaliación non continua</td>
                      <td style={{ fontWeight: 700, color: media < 5 ? "var(--rojo)" : "var(--azul-xunta)" }}>{fmt(media)}</td>
                    </tr>
                  );
                }
                return (
                  <tr key={c.trimestre}>
                    <td>{c.trimestre}º avaliación</td>
                    <td>{fmt(c.clases)} <span className="peso">{c.hayAudicion ? "70%" : "100%"}</span></td>
                    <td>{c.hayAudicion ? fmt(c.audicion) : "—"} <span className="peso">{c.hayAudicion ? "30%" : "sen datos"}</span></td>
                    <td style={{ fontWeight: 700, color: c.final < 5 ? "var(--rojo)" : "var(--azul-xunta)" }}>{fmt(c.final)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {cualificacions.map(c => {
        const alt = alternativas.find(a => a.trimestre === c.trimestre);
        if (alt) return <FilaAlternativa key={c.trimestre} matriculaId={matriculaId} trimestre={c.trimestre} alt={alt} onCambio={cargarAlternativas} />;
        return (
          <div key={c.trimestre} className="field-note" style={{ marginBottom: 10 }}>
            {c.trimestre}º trimestre en avaliación continua —{" "}
            <button className="btn btn-ghost" style={{ padding: "2px 6px", fontSize: 12 }} onClick={()=>activarAlternativa(c.trimestre)}>
              marcar como non continua
            </button>
          </div>
        );
      })}
    </div>
  );
}

// ============================================================
// TAB: Titorías
// ============================================================
function TabTitorias({ matriculaId, alumno }) {
  const [filas, setFilas] = useState(null);
  const [novo, setNovo] = useState({ data: new Date().toISOString().slice(0,10), asunto: "", mensaxe: "" });

  async function cargar() {
    const { data, error } = await sb.from("titorias").select("*").eq("matricula_id", matriculaId).order("data", { ascending: false });
    if (error) { aviso(error.message, "erro"); return; }
    setFilas(data);
  }
  useEffect(() => { cargar(); }, [matriculaId]);

  async function engadir(e) {
    e.preventDefault();
    const { data, error } = await sb.from("titorias").insert({ matricula_id: matriculaId, ...novo }).select().single();
    if (error) { aviso(error.message, "erro"); return; }
    setFilas(f => [data, ...f]);
    setNovo({ data: new Date().toISOString().slice(0,10), asunto: "", mensaxe: "" });
  }
  async function borrar(id) {
    if (!confirm("Eliminar esta titoría?")) return;
    await gardarSeguro(sb.from("titorias").delete().eq("id", id), "titorias");
    setFilas(f => f.filter(t => t.id !== id));
  }
  function enviar(titoria) {
    const ficheiro = exportarTitoriaPDF(alumno, titoria);
    abrirMailto(alumno, ficheiro);
  }

  return (
    <div>
      <div className="card">
        <h3 className="serif" style={{ marginTop: 0, fontSize: 16 }}>Nova titoría</h3>
        <form onSubmit={engadir}>
          <div className="grid2">
            <Campo label="Data" type="date" value={novo.data} onChange={e=>setNovo({...novo,data:e.target.value})} />
            <Campo label="Asunto" type="text" value={novo.asunto} onChange={e=>setNovo({...novo,asunto:e.target.value})} />
          </div>
          <label>Notas</label>
          <textarea value={novo.mensaxe} onChange={e=>setNovo({...novo,mensaxe:e.target.value})}></textarea>
          <button className="btn btn-primary" style={{ marginTop: 10 }}>Gardar titoría</button>
        </form>
      </div>

      {filas === null ? <div className="empty">Cargando…</div> : filas.length === 0 ? (
        <div className="empty">Aínda non hai titorías rexistradas.</div>
      ) : (
        <div className="card">
          {filas.map(t => (
            <div key={t.id} className="titoria-item">
              <div style={{ display: "flex", justifyContent: "space-between", gap: 8 }}>
                <strong>{t.asunto || "(sen asunto)"}</strong>
                <span style={{ color: "var(--sepia)", fontSize: 12.5, whiteSpace: "nowrap" }}>{t.data}</span>
              </div>
              {t.mensaxe && <p style={{ fontSize: 13.5, margin: "6px 0", color: "var(--tinta)" }}>{t.mensaxe}</p>}
              <div className="row-actions" style={{ marginTop: 8 }}>
                <button className="btn" style={{ fontSize: 12.5, padding: "6px 10px" }} onClick={()=>enviar(t)}>PDF + Email á familia</button>
                <button className="btn btn-danger" style={{ fontSize: 12.5, padding: "6px 10px" }} onClick={()=>borrar(t.id)}>Eliminar</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ============================================================
// FICHA DE ALUMNO (contedor de tabs)
// ============================================================
function FichaAlumno({ matricula: matriculaInicial, onVolver, onCambio }) {
  const [tab, setTab] = useState("ficha");
  const [subClases, setSubClases] = useState("clases");
  const [subAval, setSubAval] = useState("audicions");
  const [alumno, setAlumno] = useState(matriculaInicial.alumnos);
  const [matricula, setMatricula] = useState(matriculaInicial);
  const [materias, setMaterias] = useState([]);
  const cualificacions = useCualificacions(matricula.id, matricula.grao);

  async function recargarAlumno() {
    const [{ data: dAlumno }, { data: dMatricula }] = await Promise.all([
      sb.from("alumnos").select("*").eq("id", matricula.alumno_id).single(),
      sb.from("matriculas").select("*").eq("id", matricula.id).single(),
    ]);
    if (dAlumno) setAlumno(dAlumno);
    if (dMatricula) setMatricula(m => ({ ...m, ...dMatricula }));
  }
  async function recargarMaterias() {
    const { data } = await sb.from("materias").select("*, horarios_materia(*)").eq("matricula_id", matricula.id);
    if (data) setMaterias(data.map(m => ({ ...m, horarios: m.horarios_materia })));
  }
  useEffect(() => { recargarMaterias(); }, [matricula.id]);

  const TABS = [
    ["ficha", "Ficha"], ["repertorio", "Repertorio"], ["clases", "Clases"],
    ["avaliacion", "Avaliación"], ["titorias", "Titorías"],
  ];

  return (
    <div>
      <div className="wrap" style={{ paddingBottom: 0 }}>
        <button className="btn btn-ghost" style={{ padding: "4px 0", marginBottom: 6 }} onClick={onVolver}>← Alumnos</button>
        <h2 className="serif" style={{ margin: "0 0 10px", fontSize: 19, color: "var(--azul-xunta)" }}>
          {alumno.nome} {alumno.apelidos}
        </h2>
      </div>
      <div className="tabs">
        {TABS.map(([id,label]) => (
          <button key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}>{label}</button>
        ))}
      </div>
      <div className="wrap">
        {tab === "ficha" && (
          <React.Fragment>
            <TabFicha alumno={alumno} matricula={matricula} cualificacions={cualificacions||[]} materias={materias} onAtualizado={recargarAlumno} />
            <h3 className="serif" style={{ fontSize: 16, margin: "18px 0 10px" }}>Materias</h3>
            <TabMaterias matriculaId={matricula.id} onCambio={recargarMaterias} />
          </React.Fragment>
        )}
        {tab === "repertorio" && <TabRepertorio matriculaId={matricula.id} alumno={alumno} matricula={matricula} />}
        {tab === "clases" && (
          <React.Fragment>
            <div className="subtabs">
              <button className={subClases==="clases"?"active":""} onClick={()=>setSubClases("clases")}>Clases</button>
              <button className={subClases==="faltas"?"active":""} onClick={()=>setSubClases("faltas")}>Faltas</button>
            </div>
            {subClases === "clases"
              ? <TabClases matriculaId={matricula.id} grao={matricula.grao} alumno={alumno} matricula={matricula} />
              : <TabFaltas matriculaId={matricula.id} />}
          </React.Fragment>
        )}
        {tab === "avaliacion" && (
          <React.Fragment>
            <div className="subtabs">
              <button className={subAval==="audicions"?"active":""} onClick={()=>setSubAval("audicions")}>Audicións</button>
              <button className={subAval==="cualificacions"?"active":""} onClick={()=>setSubAval("cualificacions")}>Cualificacións</button>
            </div>
            {subAval === "audicions"
              ? <TabAudicions matriculaId={matricula.id} />
              : <TabCualificacions matriculaId={matricula.id} cualificacions={cualificacions} />}
          </React.Fragment>
        )}
        {tab === "titorias" && <TabTitorias matriculaId={matricula.id} alumno={alumno} />}
      </div>
    </div>
  );
}

// ============================================================
// AXUSTES (rueda de configuración): criterios de avaliación, cursos escolares, Face ID
// ============================================================
function slugify(texto) {
  const base = texto.toString().trim().toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  return (base || "criterio") + "_" + Math.random().toString(36).slice(2, 6);
}

function BloquePesos({ titulo, grao, categoriasGardadas, onGardado }) {
  const base = (Array.isArray(categoriasGardadas) && categoriasGardadas.length) ? categoriasGardadas : PESOS_DEFAULT[grao];
  const [items, setItems] = useState(() => base.map(p => ({ key: p.key, label: p.label, peso: Math.round(p.peso * 100) })));
  const [novoLabel, setNovoLabel] = useState("");
  const [gardando, setGardando] = useState(false);
  const suma = items.reduce((s,it) => s + (Number(it.peso) || 0), 0);

  function cambiarLabel(i, v) { setItems(arr => arr.map((it,idx)=> idx===i ? {...it,label:v} : it)); }
  function cambiarPeso(i, v) { setItems(arr => arr.map((it,idx)=> idx===i ? {...it,peso:v} : it)); }
  function quitar(i) {
    if (items.length <= 1) { aviso("Ten que quedar polo menos un criterio.", "erro"); return; }
    setItems(arr => arr.filter((_,idx)=>idx!==i));
  }
  function engadir() {
    if (!novoLabel.trim()) return;
    setItems(arr => [...arr, { key: slugify(novoLabel), label: novoLabel.trim(), peso: 0 }]);
    setNovoLabel("");
  }

  async function gardar() {
    setGardando(true);
    const paraGardar = items.map(it => ({ key: it.key, label: it.label, peso: (Number(it.peso) || 0) / 100 }));
    const columna = grao === "elemental" ? "pesos_ge" : "pesos_gp";
    const { data, error } = await sb.from("configuracion").update({ [columna]: paraGardar }).eq("id", "global").select().single();
    setGardando(false);
    if (error) { aviso(error.message, "erro"); return; }
    onGardado(data);
  }

  return (
    <div className="card">
      <h3 className="serif" style={{ marginTop: 0, fontSize: 16 }}>{titulo}</h3>
      {items.map((it,i) => (
        <div key={it.key} className="setting-row">
          <input type="text" style={{ flex: 1, marginRight: 8 }} value={it.label} onChange={e=>cambiarLabel(i,e.target.value)} />
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <input type="number" step="1" min="0" max="100" style={{ width: 60 }} value={it.peso} onChange={e=>cambiarPeso(i,e.target.value)} />
            <span style={{ fontSize: 13, color: "var(--sepia)" }}>%</span>
            <button type="button" className="btn btn-danger" style={{ padding: "4px 8px", fontSize: 12 }} onClick={()=>quitar(i)}>✕</button>
          </div>
        </div>
      ))}
      <div className="field-note" style={{ color: Math.round(suma) !== 100 ? "var(--rojo)" : "var(--verde)" }}>
        Suma actual: {Math.round(suma)}% {Math.round(suma) !== 100 && "— debe sumar 100%"}
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
        <input type="text" placeholder="Novo criterio (p.ex. Puntualidade)" value={novoLabel} onChange={e=>setNovoLabel(e.target.value)} style={{ flex: 1 }} />
        <button type="button" className="btn" onClick={engadir}>+ Engadir</button>
      </div>
      <div className="row-actions">
        <button className="btn btn-primary" disabled={gardando} onClick={gardar}>{gardando ? "Gardando…" : "Gardar criterios"}</button>
      </div>
    </div>
  );
}

function BloqueCursos({ anosExtra, onGardado }) {
  const [novo, setNovo] = useState("");
  async function engadir() {
    if (!/^\d{4}\/\d{4}$/.test(novo)) { aviso("Formato: 2027/2028", "erro"); return; }
    const lista = [...new Set([...(anosExtra||[]), novo])];
    const { data, error } = await sb.from("configuracion").update({ anos_extra: lista }).eq("id","global").select().single();
    if (error) { aviso(error.message, "erro"); return; }
    setNovo("");
    onGardado(data);
  }
  async function quitar(ano) {
    const lista = (anosExtra||[]).filter(a => a !== ano);
    const { data, error } = await sb.from("configuracion").update({ anos_extra: lista }).eq("id","global").select().single();
    if (error) { aviso(error.message, "erro"); return; }
    onGardado(data);
  }
  return (
    <div className="card">
      <h3 className="serif" style={{ marginTop: 0, fontSize: 16 }}>Cursos escolares engadidos</h3>
      <div className="field-note">Os últimos anos xa aparecen automaticamente; aquí podes engadir cursos adicionais (moi futuros ou antigos).</div>
      {(anosExtra||[]).map(a => (
        <div key={a} className="setting-row">
          <div className="slabel">{a}</div>
          <button className="btn btn-danger" style={{ padding: "5px 10px", fontSize: 12 }} onClick={()=>quitar(a)}>Quitar</button>
        </div>
      ))}
      <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
        <input type="text" placeholder="2027/2028" value={novo} onChange={e=>setNovo(e.target.value)} />
        <button className="btn btn-primary" onClick={engadir}>Engadir</button>
      </div>
    </div>
  );
}

function BloqueFaceId() {
  const [disponible] = useState(bioDispoñible());
  const [activo, setActivo] = useState(() => { try { return !!localStorage.getItem(CLAVE_FACEID); } catch(e) { return false; } });
  const [mostrarActivar, setMostrarActivar] = useState(false);
  const [pass, setPass] = useState("");

  async function activar(e) {
    e.preventDefault();
    try {
      const { data: sesion } = await sb.auth.getSession();
      const email = sesion.session.user.email;
      const challenge = crypto.getRandomValues(new Uint8Array(32));
      const cred = await navigator.credentials.create({ publicKey: {
        challenge, rp: { name: "Caderno do Profesor", id: location.hostname || "localhost" },
        user: { id: new TextEncoder().encode(email), name: email, displayName: email },
        pubKeyCredParams: [{ alg: -7, type: "public-key" }],
        authenticatorSelection: { authenticatorAttachment: "platform", userVerification: "required" },
        timeout: 60000,
      }});
      if (!cred) throw new Error("sen credencial");
      localStorage.setItem(CLAVE_FACEID, JSON.stringify({ email, p: btoa(pass) }));
      setActivo(true); setMostrarActivar(false); setPass("");
    } catch (err) {
      aviso("Non se puido activar Face ID / Touch ID neste dispositivo.", "erro");
    }
  }
  function desactivar() {
    localStorage.removeItem(CLAVE_FACEID);
    setActivo(false);
  }

  if (!disponible) {
    return (
      <div className="card">
        <h3 className="serif" style={{ marginTop: 0, fontSize: 16 }}>Face ID / Touch ID</h3>
        <div className="field-note">Non dispoñible neste dispositivo ou navegador.</div>
      </div>
    );
  }
  return (
    <div className="card">
      <h3 className="serif" style={{ marginTop: 0, fontSize: 16 }}>Face ID / Touch ID</h3>
      <div className="setting-row">
        <div>
          <div className="slabel">Acceder sen escribir contrasinal</div>
          <div className="sdesc">Gárdase só neste dispositivo</div>
        </div>
        <label className="toggle">
          <input type="checkbox" checked={activo} onChange={()=> activo ? desactivar() : setMostrarActivar(true)} />
          <span className="slider"></span>
        </label>
      </div>
      {mostrarActivar && (
        <form onSubmit={activar} style={{ marginTop: 6 }}>
          <label>Confirma o teu contrasinal</label>
          <input type="password" value={pass} onChange={e=>setPass(e.target.value)} required />
          <div className="row-actions">
            <button type="button" className="btn" onClick={()=>setMostrarActivar(false)}>Cancelar</button>
            <button className="btn btn-primary">Activar</button>
          </div>
        </form>
      )}
    </div>
  );
}

const TABOAS_COPIA_SEGURIDADE = [
  "alumnos", "matriculas", "materias", "horarios_materia",
  "repertorio_xeral", "repertorio_asignado", "clases", "clases_repertorio",
  "audicions", "titorias", "avaliacion_alternativa", "configuracion",
];
const ORDE_RESTAURACION = [
  "alumnos", "matriculas", "materias", "horarios_materia",
  "repertorio_xeral", "repertorio_asignado", "clases", "clases_repertorio",
  "audicions", "titorias", "avaliacion_alternativa",
];

async function exportarCopiaSeguridade() {
  const datos = { version: 1, exportado_en: new Date().toISOString() };
  for (const t of TABOAS_COPIA_SEGURIDADE) {
    const { data, error } = await sb.from(t).select("*");
    if (error) { aviso(`Erro exportando ${t}: ` + error.message, "erro"); return false; }
    datos[t] = data;
  }
  const blob = new Blob([JSON.stringify(datos, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `caderno_copia_${new Date().toISOString().slice(0,10)}.json`;
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
  return true;
}

async function importarCopiaSeguridade(ficheiro) {
  let datos;
  try { datos = JSON.parse(await ficheiro.text()); }
  catch (e) { aviso("O arquivo non é un JSON válido.", "erro"); return; }
  if (!datos || !Array.isArray(datos.alumnos)) { aviso("Este arquivo non parece unha copia de seguridade válida do Caderno do Profesor.", "erro"); return; }
  if (!confirm("Isto SUBSTITUIRÁ TODOS os datos actuais (alumnos, clases, repertorio, todo) polo contido desta copia. Esta acción NON se pode desfacer.\n\nQueres continuar?")) return;
  if (!confirm("Confírmao outra vez: perderás calquera dato gardado despois da data desta copia. Seguro que queres restaurar?")) return;

  const { error: eDel1 } = await sb.from("alumnos").delete().not("id", "is", null);
  if (eDel1) { aviso("Erro borrando datos actuais: " + eDel1.message, "erro"); return; }
  const { error: eDel2 } = await sb.from("repertorio_xeral").delete().not("id", "is", null);
  if (eDel2) { aviso("Erro borrando repertorio xeral: " + eDel2.message, "erro"); return; }

  for (const t of ORDE_RESTAURACION) {
    const filas = datos[t];
    if (filas && filas.length) {
      const { error } = await sb.from(t).insert(filas);
      if (error) { aviso(`Erro restaurando ${t}: ` + error.message + "\n\nA restauración quedou incompleta.", "erro"); return; }
    }
  }
  if (Array.isArray(datos.configuracion) && datos.configuracion[0]) {
    const { id, ...resto } = datos.configuracion[0];
    await gardarSeguro(sb.from("configuracion").update(resto).eq("id", "global"), "configuracion");
  }
  aviso("Copia restaurada correctamente. A páxina vaise recargar.", "erro");
  window.location.reload();
}

function BloqueCopiaSeguridade() {
  const [exportando, setExportando] = useState(false);
  const [importando, setImportando] = useState(false);
  const inputRef = useRef(null);

  async function exportar() {
    setExportando(true);
    await exportarCopiaSeguridade();
    setExportando(false);
  }
  async function onFicheiro(e) {
    const ficheiro = e.target.files[0];
    if (!ficheiro) return;
    setImportando(true);
    await importarCopiaSeguridade(ficheiro);
    setImportando(false);
    e.target.value = "";
  }

  return (
    <div className="card">
      <h3 className="serif" style={{ marginTop: 0, fontSize: 16 }}>Copia de seguridade</h3>
      <div className="field-note">Exporta todo o caderno (alumnos, clases, repertorio, cualificacións…) a un arquivo que podes gardar e, se algún día o necesitas, importar de novo.</div>
      <div className="row-actions">
        <button className="btn btn-primary" disabled={exportando} onClick={exportar}>{exportando ? "Exportando…" : "Exportar copia"}</button>
      </div>
      <div className="field-note" style={{ marginTop: 16, color: "var(--rojo)" }}>
        Importar unha copia SUBSTITÚE todos os datos actuais — úsao só para restaurar, non para engadir.
      </div>
      <input ref={inputRef} type="file" accept="application/json" style={{ display: "none" }} onChange={onFicheiro} />
      <div className="row-actions">
        <button className="btn btn-danger" disabled={importando} onClick={()=>inputRef.current.click()}>{importando ? "Importando…" : "Importar copia"}</button>
      </div>
    </div>
  );
}

