function BloquePianistas() {
  const [lista, setLista] = useState(null);
  const [novo, setNovo] = useState("");

  async function cargar() {
    const { data, error } = await sb.from("pianistas").select("*").order("nome");
    if (error) { aviso(error.message, "erro"); return; }
    setLista(data);
  }
  useEffect(() => { cargar(); }, []);

  async function engadir(e) {
    e.preventDefault();
    if (!novo.trim()) return;
    const ok = await gardarSeguro(sb.from("pianistas").insert({ nome: novo.trim() }), "pianista");
    if (ok) { setNovo(""); cargar(); }
  }
  async function renomear(p) {
    const nomeNovo = prompt("Novo nome do pianista:", p.nome);
    if (!nomeNovo || !nomeNovo.trim() || nomeNovo.trim() === p.nome) return;
    const ok = await gardarSeguro(sb.from("pianistas").update({ nome: nomeNovo.trim() }).eq("id", p.id), "pianista");
    if (!ok) return;
    // arrastrar o cambio ás materias que xa o tiñan asignado
    await gardarSeguro(sb.from("materias").update({ pianista_acompanante: nomeNovo.trim() }).eq("pianista_acompanante", p.nome), "materias");
    cargar();
  }
  async function eliminar(p) {
    const { count } = await sb.from("materias").select("id", { count: "exact", head: true }).eq("pianista_acompanante", p.nome);
    const aviso_extra = count ? `\n\nAtención: ${count} alumno(s) téñeno asignado e quedarán sen pianista.` : "";
    if (!confirm(`Eliminar a ${p.nome} da lista?${aviso_extra}`)) return;
    const ok = await gardarSeguro(sb.from("pianistas").delete().eq("id", p.id), "pianista");
    if (!ok) return;
    if (count) await gardarSeguro(sb.from("materias").update({ pianista_acompanante: null }).eq("pianista_acompanante", p.nome), "materias");
    cargar();
  }

  return (
    <div className="card">
      <h3 className="serif" style={{ marginTop: 0, fontSize: 16 }}>Pianistas acompañantes</h3>
      <div className="field-note">A lista que aparece ao asignar pianista a un alumno. Se renomeas un pianista, actualízase en todos os alumnos que o teñan.</div>
      {lista === null && <div className="field-note">Cargando…</div>}
      {lista !== null && lista.length === 0 && <div className="field-note">Aínda non hai pianistas na lista.</div>}
      {(lista || []).map(p => (
        <div key={p.id} className="setting-row">
          <div className="slabel">{p.nome}</div>
          <div style={{ display: "flex", gap: 6 }}>
            <button className="btn btn-ghost" style={{ fontSize: 11.5, padding: "4px 8px" }} onClick={()=>renomear(p)}>Renomear</button>
            <button className="btn btn-danger" style={{ fontSize: 11.5, padding: "4px 8px" }} onClick={()=>eliminar(p)}>✕</button>
          </div>
        </div>
      ))}
      <form onSubmit={engadir} style={{ display: "flex", gap: 8, marginTop: 12 }}>
        <input type="text" placeholder="Nome do pianista" value={novo} onChange={e=>setNovo(e.target.value)} style={{ flex: 1 }} />
        <button className="btn btn-primary">+ Engadir</button>
      </form>
    </div>
  );
}

function Axustes({ config, anoEscolar, onVolver, onActualizado }) {
  return (
    <div className="wrap">
      <button className="btn btn-ghost" style={{ padding: "4px 0", marginBottom: 14 }} onClick={onVolver}>← Volver</button>
      <h2 className="serif" style={{ marginBottom: 16, fontSize: 21 }}>Axustes</h2>
      <BloquePesos titulo="Criterios — Grao Elemental" grao="elemental" categoriasGardadas={config.pesos_ge} onGardado={onActualizado} />
      <BloquePesos titulo="Criterios — Grao Profesional" grao="profesional" categoriasGardadas={config.pesos_gp} onGardado={onActualizado} />
      <BloqueCursos anosExtra={config.anos_extra} onGardado={onActualizado} />
      <BloquePianistas />
      <BloqueFaceId />
      <BloqueInformeSustituto anoEscolar={anoEscolar} />
      <BloqueCopiaSeguridade />
    </div>
  );
}

// ============================================================
// APP
// ============================================================
function App() {
  const [sesion, setSesion] = useState(undefined); // undefined=cargando, null=sen sesión
  const anoActual = anoEscolarActual();
  const [anoEscolar, setAnoEscolar] = useState(anoActual);
  const [matriculaAberta, setMatriculaAberta] = useState(null);
  const [config, setConfig] = useState(null);
  const [vista, setVista] = useState("alumnos"); // alumnos | repertorio | axustes

  useEffect(() => {
    sb.auth.getSession().then(({ data }) => setSesion(data.session));
    const { data: sub } = sb.auth.onAuthStateChange((_e, s) => setSesion(s));
    return () => sub.subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (!sesion) return;
    (async () => {
      let { data } = await sb.from("configuracion").select("*").eq("id", "global").maybeSingle();
      if (!data) {
        const { data: creado } = await sb.from("configuracion").insert({ id: "global" }).select().single();
        data = creado;
      }
      aplicarPesosDesdeConfig(data);
      setConfig(data);
    })();
  }, [sesion]);

  if (sesion === undefined) return <div className="empty">Cargando…</div>;
  if (!sesion) return <Login onLogged={() => {}} />;
  if (!config) return <div className="empty">Cargando…</div>;

  function irA(v) { setVista(v); setMatriculaAberta(null); }

  return (
    <div>
      <div className="topbar">
        <div className="brand">
          <img src={LOGO_CMUS} alt="CMUS" style={{ height: 26, width: "auto", maxWidth: 140, objectFit: "contain", display: "block", marginBottom: 3 }} />
          <small>Caderno do Profesor · Jorge Montes</small>
        </div>
        <button className={"icon" + (vista==="alumnos" ? " activo" : "")} onClick={()=>irA("alumnos")}>Alumnos</button>
        <button className={"icon" + (vista==="repertorio" ? " activo" : "")} onClick={()=>irA("repertorio")}>Repertorio</button>
        <button className={"icon" + (vista==="pianistas" ? " activo" : "")} onClick={()=>irA("pianistas")}>Pianistas</button>
        <button className={"icon" + (vista==="audicions" ? " activo" : "")} onClick={()=>irA("audicions")}>Audicións</button>
        <button className={"icon" + (vista==="tarefas" ? " activo" : "")} onClick={()=>irA("tarefas")}>Tarefas</button>
        {vista === "alumnos" && (
          <select value={anoEscolar} onChange={e=>{ setAnoEscolar(e.target.value); setMatriculaAberta(null); }}>
            {anosEscolaresDispoñibles(anoActual, config.anos_extra).map(a => <option key={a} value={a}>{a}</option>)}
          </select>
        )}
        <button className={"icon" + (vista==="axustes" ? " activo" : "")} onClick={()=>irA("axustes")}>⚙</button>
        <button className="icon" onClick={() => sb.auth.signOut()}>Saír</button>
      </div>
      <Avisos />

      {vista === "axustes" ? (
        <Axustes config={config} anoEscolar={anoEscolar} onVolver={()=>irA("alumnos")}
          onActualizado={(novoConfig)=>{ aplicarPesosDesdeConfig(novoConfig); setConfig(novoConfig); }} />
      ) : vista === "repertorio" ? (
        <RepertorioXeral />
      ) : vista === "pianistas" ? (
        <PianistasXeral anoEscolar={anoEscolar} />
      ) : vista === "audicions" ? (
        <AudicionsXerais anoEscolar={anoEscolar} />
      ) : vista === "tarefas" ? (
        <TarefasXerais />
      ) : matriculaAberta ? (
        <FichaAlumno matricula={matriculaAberta} onVolver={() => setMatriculaAberta(null)} />
      ) : (
        <ListaAlumnos anoEscolar={anoEscolar} onAbrir={(m) => setMatriculaAberta(m)} />
      )}
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
